def get_table_resize(table_data, table_col_count, column_widths, page_width) -> bool:
    resize = False
    try:
        resize = table_data['fitToPageWidth']
    except:
        total_table_width = sum(column_widths)
        if total_table_width > page_width:
            resize = True
    return resize

def process_query(self, query: Query, request_settings: RequestSettings) -> None:

    def process_column(exp: Expression) -> Expression:
        if isinstance(exp, Column):
            if exp.column_name == 'group_id':
                return FunctionCall(exp.alias, 'nullIf', (Column(None, exp.table_name, exp.column_name), Literal(None, 0)))
        return exp
    query.transform_expressions(process_column)

import time
import uuid

def logMsg(self, msg, importance=5, msgType='status', exception=(None, None, None), **kwargs):
    try:
        currentDir = self.manager.getCurrentDir()
    except:
        currentDir = None
    if isinstance(currentDir, DirHandle):
        kwargs['currentDir'] = currentDir.name()
    now = str(time.strftime('%Y.%m.%d %H:%M:%S'))
    name = 'LogEntry_' + str(uuid.uuid4())
    entry = {'docs': None, 'reasons': None, 'message': msg, 'timestamp': now, 'importance': importance, 'msgType': msgType, 'exception': exception}
    for k in kwargs:
        entry[k] = kwargs[k]
    self.processEntry(entry)
    self.saveEntry({name: entry})
    self.displayEntry(entry)

def get_working_copy_status_json(repo):
    if repo.is_bare:
        return None
    result = []
    for part in repo.working_copy.parts:
        table_wc = part.tabular
        table_wc_path = table_wc.clean_location if table_wc else None
        result.append({'path': table_wc_path, 'changes': get_diff_status_json(part)})
    return result

def connect(self):
    log.info('Attempting to connect to news server...')
    ssl = config.news.pop('ssl', False)
    compression = config.news.pop('compression', False)
    try:
        if ssl:
            self.connection = nntplib.NNTP_SSL(**config.news)
        else:
            self.connection = nntplib.NNTP(**config.news)
        if compression:
            log.info('Compression enabled for the connection.')
        else:
            log.info('Compression not enabled.')
    except Exception as e:
        log.error('Could not connect to news server: ' + str(e))
        return False
    log.info('Connected!')
    return True

def compute_hint_frame_locations(self, operations):
    op = operations[-1]
    if op.getopnum() != rop.JUMP:
        return
    self.final_jump_op = op
    descr = op.getdescr()
    assert isinstance(descr, TargetToken)
    if descr._ll_loop_code != 0:
        self._compute_hint_frame_locations_from_descr(descr)

def run_ingest_job_and_kick_scheduler_on_completion(self, args: IngestArgsType):
    self._run_ingest_job(args)
    while not self.is_ingest_job_complete():
        time.sleep(0.1)
    self.kick_scheduler()
    logging.info('Done running task. Returning from run_ingest_job_and_kick_scheduler_on_completion')

