def sanitize_snmp_table_columns(columns):
    endoids = []
    for (fetchoid, column) in columns:
        for (o, value) in column:
            endoid = extract_end_oid(fetchoid, o)
            if endoid not in endoids:
                endoids.append(endoid)
    endoids.sort(cmp=cmp_oids)
    new_columns = []
    for (fetchoid, column) in columns:
        needs_sorting = True
        if len(column) == len(endoids):
            sorted_column = sorted(column, key=lambda x: extract_end_oid(fetchoid, x[0]))
            needs_sorting = sorted_column == column
        if needs_sorting:
            column.sort(cmp=cmp_oid_pairs)
        i = 0
        new_column = []
        for (o, value) in column:
            eo = extract_end_oid(fetchoid, o)
            if len(column) != len(endoids):
                while i < len(endoids) and endoids[i] != eo:
                    new_column.append('')
                    i += 1
            new_column.append(value)
            i += 1
        while i < len(endoids):
            new_column.append('')
            i += 1
        new_columns.append(new_column)
    return new_columns

def append(self, relpath, f, mode=None):
    abspath = self._abspath(relpath)
    fp = None
    try:
        try:
            fp = open(abspath, 'ab')
            if mode is not None:
                current_mode = stat.S_IMODE(os.lstat(abspath).st_mode)
                if current_mode != mode:
                    os.chmod(abspath, mode)
        except (IOError, OSError) as e:
            self._translate_error(e, relpath)
        fp.seek(0, 2)
        result = fp.tell()
        self._pump(f, fp)
    finally:
        if fp is not None:
            fp.close()
    return result

def _name2(self, v, current_klass, attr_name):
    obj = v.name
    if obj in self.method_imported_globals:
        call_name = UU + self.modpfx() + obj + '.' + attr_name
    elif obj in self.imported_classes:
        attr_str = '.prototype.__class__.' + attr_name
        call_name = UU + self.imported_classes[obj] + '__' + obj + attr_str
    elif obj in self.module_imports():
        call_name = obj + '.' + attr_name
    else:
        call_name = UU + self._name(v, current_klass) + '.' + attr_name
    return call_name

def _set_provided_start_time_for_booking_descendant(entity: Any, parent_booking_admission_date: date, context_registry: '_SnapshotContextRegistry') -> None:
    if parent_booking_admission_date:
        if isinstance(entity, BookingTypeA):
            context_registry.snapshot_context(entity).provided_start_time = _date_to_datetime(parent_booking_admission_date) + timedelta(hours=1)
        elif isinstance(entity, BookingTypeB):
            context_registry.snapshot_context(entity).provided_start_time = _date_to_datetime(parent_booking_admission_date) + timedelta(hours=2)
        else:
            context_registry.snapshot_context(entity).provided_start_time = _date_to_datetime(parent_booking_admission_date)

def _MustBreakBefore(prev_token, cur_token):
    if prev_token.is_comment:
        return True
    if cur_token.is_string and prev_token.is_string:
        return True
    if prev_token.is_keyword:
        return True
    return False

def topics_for(products, parent=False):
    statsd.incr('wiki.facets.topics_for.db')
