            form.password.errors.append('Invalid password')
            return render_template('views/service-settings/confirm.html', heading='Turn off all outgoing notifications', destructive=True, form=form, service_id=service_id)
        service['active'] = True
        update_service(service)
        return redirect(url_for('.service_settings', service_id=service_id))
    return render_template('views/service-settings/confirm.html', heading='Turn off all outgoing notifications', destructive=True, form=form, service_id=service_id)

