def tobsr(self, blocksize=None, copy=True):
    if blocksize == (1, 1):
        from bsr import bsr_matrix
        arg1 = (self.data.reshape(-1, 1, 1), self.indices, self.indptr)
        return bsr_matrix(arg1, shape=self.shape, copy=copy)
    else:
        from bsr import bsr_matrix
        n_rows = self.shape[0]
        n_cols = self.shape[1]
        bsr_data = []
        bsr_indices = []
        bsr_indptr = [0]
        block_row_count = (n_rows + blocksize[0] - 1) // blocksize[0]
        block_col_count = (n_cols + blocksize[1] - 1) // blocksize[1]
        for block_row in range(block_row_count):
            for block_col in range(block_col_count):
                block_data = self.extract_block(block_row, block_col, blocksize)
                if block_data:
                    bsr_data.append(block_data)
                    bsr_indices.append(block_col)
            bsr_indptr.append(len(bsr_data))
        return bsr_matrix((bsr_data, bsr_indices, bsr_indptr), shape=self.shape, copy=copy)

    def extract_block(self, block_row, block_col, blocksize):
        pass

