    for member in member_list:
        member.user.profile
        member_data = {'user_id': str(uuid.UUID(bytes=member.user.id)), 'user_profile': member.user.profile}
        result.append(member_data)
    return result

def set_doc_variables(item, job, params):
    change = item.change
    doc_subpath = ''
    if hasattr(change, 'ref'):
        tag = re.match('^refs/tags/(.*)', change.ref)
        if tag:
            doc_subpath = tag.group(1)
        else:
            doc_subpath = change.ref
    elif hasattr(change, 'refspec'):
        doc_subpath = change.branch
    if doc_subpath:
        params['DOC_SUBPATH'] = doc_subpath
    if 'ZUUL_PROJECT' in params:
        raw_project = params['ZUUL_PROJECT']
        if raw_project in doc_destination:
            raw_project = doc_destination[raw_project]
        elif raw_project.startswith('mediawiki/extensions/'):
            raw_project = raw_project.split('/')[-1]
        params['DOC_PROJECT'] = raw_project.replace('/', '-')

def getWeaponSystemData(fit):
    weaponSystems = []
    groups = {}
    defaultSpoolValue = 1
    spoolOptions = SpoolOptions(SpoolType.SCALE, defaultSpoolValue, False)
    for mod in fit.modules:
        if mod.getDps(spoolOptions=spoolOptions).total > 0:
            keystr = str(mod.itemID) + '-' + str(mod.chargeID)
            if keystr in groups:
                groups[keystr][1] += 1
            else:
                groups[keystr] = [mod, 1]
    for wepGroup in groups.values():
        stats = wepGroup[0]
        n = wepGroup[1]
        tracking = 0
        maxVelocity = 0
        explosionDelay = 0
        damageReductionFactor = 0
        explosionRadius = 0
        explosionVelocity = 0
        aoeFieldRange = 0
        typeing = 'None'
        if stats.charge:
            name = stats.item.name + ', ' + stats.charge.name
        else:
            name = stats.item.name
        if stats.hardpoint == Hardpoint.TURRET:
            tracking = stats.getModifiedItemAttr('trackingSpeed')
            typeing = 'Turret'
        elif stats.hardpoint == Hardpoint.MISSILE or 'Bomb Launcher' in stats.item.name:
            maxVelocity = stats.getModifiedChargeAttr('maxVelocity')
            explosionDelay = stats.getModifiedChargeAttr('explosionDelay')
            damageReductionFactor = stats.getModifiedChargeAttr('aoeDamageReductionFactor')
            explosionRadius = stats.getModifiedChargeAttr('aoeCloudSize')
            explosionVelocity = stats.getModifiedChargeAttr('aoeVelocity')
            typeing = 'Missile'
        elif stats.hardpoint == Hardpoint.NONE:
            aoeFieldRange = stats.getModifiedItemAttr('empFieldRange')
            typeing = 'SmartBomb'
        if stats.item.group.name == 'Super Weapon' and stats.maxRange is None:
            maxRange = 300000
        else:
            maxRange = stats.maxRange
        statDict = {'dps': stats.getDps(spoolOptions=spoolOptions).total * n, 'capUse': stats.capUse * n, 'falloff': stats.falloff, 'type': typeing, 'name': name, 'optimal': maxRange, 'numCharges': stats.numCharges, 'numShots': stats.numShots, 'reloadTime': stats.reloadTime, 'cycleTime': stats.cycleTime, 'volley': stats.getVolley(spoolOptions=spoolOptions).total * n, 'tracking': tracking, 'maxVelocity': maxVelocity, 'explosionDelay': explosionDelay, 'damageReductionFactor': damageReductionFactor, 'explosionRadius': explosionRadius, 'explosionVelocity': explosionVelocity, 'aoeFieldRange': aoeFieldRange, 'damageMultiplierBonusMax': stats.getModifiedItemAttr('damageMultiplierBonusMax'), 'damageMultiplierBonusPerCycle': stats.getModifiedItemAttr('damageMultiplierBonusPerCycle')}
        weaponSystems.append(statDict)
    for drone in fit.drones:
        if drone.getDps().total > 0 and drone.amountActive > 0:
            droneAttr = drone.getModifiedItemAttr
            newTracking = droneAttr('trackingSpeed') / (droneAttr('optimalSigRadius') / 40000)
            statDict = {'dps': drone.getDps().total, 'cycleTime': drone.cycleTime, 'type': 'Drone', 'optimal': drone.maxRange, 'name': drone.item.name, 'falloff': drone.falloff, 'maxSpeed': droneAttr('maxVelocity'), 'tracking': newTracking, 'volley': drone.getVolley().total}
            weaponSystems.append(statDict)
    for fighter in fit.fighters:
        if fighter.getDps().total > 0 and fighter.amountActive > 0:
            fighterAttr = fighter.getModifiedItemAttr
            abilities = []
            if 'fighterAbilityAttackMissileDamageEM' in fighter.item.attributes.keys():
                baseRef = 'fighterAbilityAttackMissile'
                ability = EfsPort.getFighterAbilityData(fighterAttr, fighter, baseRef)
                abilities.append(ability)
            if 'fighterAbilityMissilesDamageEM' in fighter.item.attributes.keys():
                baseRef = 'fighterAbilityMissiles'
                ability = EfsPort.getFighterAbilityData(fighterAttr, fighter, baseRef)
                abilities.append(ability)
            statDict = {'dps': fighter.getDps().total, 'type': 'Fighter', 'name': fighter.item.name, 'maxSpeed': fighterAttr('maxVelocity'), 'abilities': abilities, 'ehp': fighterAttr('shieldCapacity') / 0.8875 * fighter.amountActive, 'volley': fighter.getVolley().total, 'signatureRadius': fighterAttr('signatureRadius')}
            weaponSystems.append(statDict)
    return weaponSystems

def RunStateMethod(self, method_name: str, request: Optional[rdf_flow_runner.RequestState]=None, responses: Optional[Sequence[rdf_flow_objects.FlowMessage]]=None) -> None:
    client_id = self.rdf_flow.client_id
    deadline = self.rdf_flow.processing_deadline
    if deadline and rdfvalue.RDFDatetime.Now() > deadline:
        raise FlowError('Processing time for flow %s on %s expired.' % (self.rdf_flow.flow_id, self.rdf_flow.client_id))
    self.rdf_flow.current_state = method_name
    if request and responses:
        logging.debug('Running %s for flow %s on %s, %d responses.', method_name, self.rdf_flow.flow_id, client_id, len(responses))
    else:
        logging.debug('Running %s for flow %s on %s', method_name, self.rdf_flow.flow_id, client_id)
    try:
        try:
            method = getattr(self, method_name)
        except AttributeError:
            raise ValueError('Flow %s has no state method %s' % (self.__class__.__name__, method_name))
        responses = flow_responses.Responses.FromResponses(request=request, responses=responses)
        if responses.status is not None:
            self.SaveResourceUsage(responses.status)
        GRR_WORKER_STATES_RUN.Increment()
        if method_name == 'Start':
            FLOW_STARTS.Increment(fields=[self.rdf_flow.flow_class_name])
            method()
        else:
            method(responses)
        if self.replies_to_process:
            if self.rdf_flow.parent_hunt_id and (not self.rdf_flow.parent_flow_id):
                self._ProcessRepliesWithHuntOutputPlugins(self.replies_to_process)
            else:
                self._ProcessRepliesWithFlowOutputPlugins(self.replies_to_process)
            self.replies_to_process = []
    except flow.FlowResourcesExceededError as e:
        FLOW_ERRORS.Increment(fields=[self.rdf_flow.flow_class_name])
        logging.info('Flow %s on %s exceeded resource limits: %s.', self.rdf_flow.flow_id, client_id, str(e))
        self.Error(error_message=str(e))
    except Exception as e:
        msg = str(e)
        FLOW_ERRORS.Increment(fields=[self.rdf_flow.flow_class_name])
        self.Error(error_message=msg, backtrace=traceback.format_exc())

def hover_response_for_position(self, path: Path, position: lsp.LspPosition) -> lsp.HoverResponse:
    type_info = self.lookup_type(path, position)
    return lsp.HoverResponse(contents=type_info)

def spawn_locusts(self, spawn_count=None, stop_timeout=None, wait=False):
    if spawn_count is None:
        spawn_count = self.num_clients
    if self.num_requests is not None:
        RequestStats.global_max_requests = self.num_requests
    bucket = self.weight_locusts(spawn_count, stop_timeout)
    spawn_count = len(bucket)
    if self.state == STATE_INIT or self.state == STATE_STOPPED:
        self.state = STATE_HATCHING
        self.num_clients = spawn_count
    else:
        self.num_clients += spawn_count
    logger.info('Hatching and swarming %i clients at the rate %g clients/s...' % (spawn_count, self.hatch_rate))
    occurence_count = dict([(l.__name__, 0) for l in self.locust_classes])

    def hatch():
        sleep_time = 1.0 / self.hatch_rate
        while True:
            if not bucket:
                logger.info('All locusts hatched: %s' % ', '.join(['%s: %d' % (name, count) for (name, count) in occurence_count.iteritems()]))
                events.hatch_complete.fire(self.num_clients)
                return
            locust = bucket.pop(random.randint(0, len(bucket) - 1))
            occurence_count[locust.__name__] += 1

            def start_locust(_):
                try:
                    locust().run()
                except GreenletExit:
                    pass
            new_locust = self.locusts.spawn(start_locust, locust)
            if len(self.locusts) % 10 == 0:
                logger.debug('%i locusts hatched' % len(self.locusts))
            gevent.sleep(sleep_time)
    hatch()
    if wait:
        self.locusts.join()
        logger.info('All locusts dead\n')
        events.all_locusts_dead.fire(self.request_stats)

@events.all_locusts_dead.add_listener
def on_all_locusts_dead(request_stats):
    print_stats(request_stats)
    print_percentile_stats(request_stats)

def setkey(self, propname):
    if self.key:
        if propname == self.key:
            return
        self.update_key_index(self.key, propname)
        raise ValueError, "%s already indexed on %s"%(self.classname,
            self.key)
    prop = self.properties.get(propname, None)
    if prop is None:
        prop = self.privateprops.get(propname, None)
    if prop is None:
        raise KeyError, "no property %s" % propname
    if not isinstance(prop, hyperdb.String):
        raise TypeError, "%s is not a String" % propname
    self.key = propname
    iv = self.db._db.view('_%s' % self.classname)
    if self.db.fastopen and iv.structure():
        return
    self.db.dirty = 1
    iv = self.db._db.getas('_%s[k:S,i:I]' % self.classname)
    iv = iv.ordered(1)
    for row in self.getview():
        iv.append(k=getattr(row, propname), i=row.id)
    self.db.commit()
def update_key_index(self, old_key, new_key):
    iv = self.db._db.view('_%s' % self.classname)
    for row in self.getview():
        if getattr(row, old_key) is not None:
            iv.remove(k=getattr(row, old_key), i=row.id)
    for row in self.getview():
        iv.append(k=getattr(row, new_key), i=row.id)
    self.db.commit()

def __init__(self, record: record.Record, modifications: types.NormalizedAttributes) -> None:
    super().__init__(record_dn=record.dn)
    self.modifications = modifications

def create(entity_type=None, entity_id=None):
    if not (entity_id or entity_type):
        for allowed_type in ENTITY_TYPES:
            if (mbid := request.args.get(allowed_type)):
                entity_type = allowed_type
                entity_id = mbid
                break
        if entity_type:
            return redirect(url_for('.create', entity_type=entity_type, entity_id=entity_id))
        flash.info(gettext('Please choose an entity to review.'))
        return redirect(url_for('search.selector', next=url_for('.create')))
    if entity_type not in ENTITY_TYPES:
        raise BadRequest("You can't write reviews about this type of entity.")
    if current_user.is_blocked:
        flash.error(gettext('You are not allowed to write new reviews because your account has been blocked by a moderator.'))
        return redirect(url_for('user.reviews', user_id=current_user.id))
    (reviews, count) = db_review.list_reviews(user_id=current_user.id, entity_id=entity_id, inc_drafts=True, inc_hidden=True)
    review = reviews[0] if count != 0 else None
    if review:
        if review['is_draft']:
            return redirect(url_for('review.edit', id=review['id']))
        elif review['is_hidden']:
            return redirect(url_for('review.entity', id=review['id']))
        else:
            flash.error(gettext('You have already published a review for this entity'))
            return redirect(url_for('review.entity', id=review['id']))
    if current_user.is_review_limit_exceeded:
        flash.error(gettext('You have exceeded your limit of reviews per day.'))
        return redirect(url_for('user.reviews', user_id=current_user.id))
    form = ReviewCreateForm(default_license_id=current_user.license_choice, default_language=get_locale())
    if form.validate_on_submit():
        is_draft = form.state.data == 'draft'
        if form.text.data == '':
            form.text.data = None
        review = db_review.create(user_id=current_user.id, entity_id=entity_id, entity_type=entity_type, text=form.text.data, rating=form.rating.data, license_id=form.license_choice.data, language=form.language.data, is_draft=is_draft)
        if form.remember_license.data:
            db_users.update(current_user.id, user_new_info={'license_choice': form.license_choice.data})
        if is_draft:
            flash.success(gettext('Review has been saved!'))
        else:
            flash.success(gettext('Review has been published!'))
        return redirect(url_for('.entity', id=review['id']))
    try:
        _entity = get_entity_by_id(entity_id, entity_type)
        data = {'form': form, 'entity_type': entity_type, 'entity': _entity}
    except NoDataFoundException:
        raise NotFound(gettext("Sorry, we couldn't find a %s with that MusicBrainz ID." % entity_type))
    data['entity_title'] = get_entity_title(_entity)
    if entity_type == 'release_group':
        data['spotify_mappings'] = mbspotify.mappings(entity_id)
        data['soundcloud_url'] = soundcloud.get_url(entity_id)
    if not form.errors:
        flash.info(gettext('Please provide some text or a rating for this review.'))
    return render_template('review/modify/write.html', **data)

import socket
import ssl
import time
import re

def to_bytes(s):
    return s.encode('utf-8')

def to_native(b):
    return b.decode('utf-8')

def send_msg(msg, server='localhost', port='6667', channel=None, nick_to=None, key=None, topic=None, nick='ansible', color='none', passwd=False, timeout=30, use_ssl=False, part=True, style=None):
    nick_to = [] if nick_to is None else nick_to
    colornumbers = {'white': '00', 'black': '01', 'blue': '02', 'green': '03', 'red': '04', 'brown': '05', 'purple': '06', 'orange': '07', 'yellow': '08', 'light_green': '09', 'teal': '10', 'light_cyan': '11', 'light_blue': '12', 'pink': '13', 'gray': '14', 'light_gray': '15'}
    stylechoices = {'bold': '\x02', 'underline': '\x1f', 'reverse': '\x16', 'italic': '\x1d'}
    try:
        styletext = stylechoices[style]
    except Exception:
        styletext = ''
    try:
        colornumber = colornumbers[color]
        colortext = '\x03' + colornumber
    except Exception:
        colortext = ''
    message = styletext + colortext + msg
    irc = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    if use_ssl:
        context = ssl.create_default_context()
        context.check_hostname = False
        context.verify_mode = ssl.CERT_NONE
        irc = context.wrap_socket(irc)
    irc.connect((server, int(port)))
    if passwd:
        irc.send(to_bytes('PASS %s\r\n' % passwd))
    irc.send(to_bytes('NICK %s\r\n' % nick))
    irc.send(to_bytes('USER %s %s %s :ansible IRC\r\n' % (nick, nick, nick)))
    motd = ''
    start = time.time()
    while 1:
        motd += to_native(irc.recv(1024))
        match = re.search('^:\\S+ 00[1-4] (?P<nick>\\S+) :', motd, flags=re.M)
        if match:
            nick = match.group('nick')
            break
        elif time.time() - start > timeout:
            raise Exception('Timeout waiting for IRC server welcome response')
        time.sleep(0.5)
    if channel:
        if key:
            irc.send(to_bytes('JOIN %s %s\r\n' % (channel, key)))
        else:
            irc.send(to_bytes('JOIN %s\r\n' % channel))
        join = ''
        start = time.time()
        while 1:
            join += to_native(irc.recv(1024))
            if re.search('^:\\S+ 366 %s %s :' % (nick, channel), join, flags=re.M | re.I):
                break
            elif time.time() - start > timeout:
                raise Exception('Timeout waiting for IRC JOIN response')
            time.sleep(0.5)
        if topic is not None:
            irc.send(to_bytes('TOPIC %s :%s\r\n' % (channel, topic)))
            time.sleep(1)
    if nick_to:
        for nick in nick_to:
            irc.send(to_bytes('PRIVMSG %s :%s\r\n' % (nick, message)))
    if channel:
        irc.send(to_bytes('PRIVMSG %s :%s\r\n' % (channel, message)))
    time.sleep(1)
    if part:
        if channel:
            irc.send(to_bytes('PART %s\r\n' % channel))
        irc.send(to_bytes('QUIT\r\n'))
        time.sleep(1)
    irc.close()

def excerpt(self, source_paths, workdir, conform):
    encoding = conform.get('encoding')
    csvsplit = conform.get('csvsplit', ',')
    known_paths = ExcerptDataTask._get_known_paths(source_paths, workdir, conform, self.known_types)
    if not known_paths:
        return (None, None)
    data_path = known_paths[0]
    (_, data_ext) = os.path.splitext(data_path.lower())
    if data_ext in ('.geojson', '.json'):
        data_path = ExcerptDataTask._sample_geojson_file(data_path)
    format_string = conform.get('format')
    if format_string == 'csv':
        return ExcerptDataTask._excerpt_csv_file(data_path, encoding, csvsplit)
    ogr_data_path = normalize_ogr_filename_case(data_path)
    datasource = ogr.Open(ogr_data_path, 0)
    layer = datasource.GetLayer()
    if not encoding:
        encoding = guess_source_encoding(datasource, layer)
    if data_ext == '.csv' and encoding not in ('utf8', 'utf-8'):
        return ExcerptDataTask._excerpt_csv_file(data_path, encoding, csvsplit)
    layer_defn = layer.GetLayerDefn()
    fieldcount = layer_defn.GetFieldCount()
    fieldnames = [layer_defn.GetFieldDefn(i).GetName() for i in range(fieldcount)]
    fieldnames = [f.decode(encoding) if hasattr(f, 'decode') else f for f in fieldnames]
    data_sample = [fieldnames]
    for (feature, _) in zip(layer, range(5)):
        row = [feature.GetField(i) for i in range(fieldcount)]
        row = [v.decode(encoding) if hasattr(v, 'decode') else v for v in row]
        data_sample.append(row)
    if len(data_sample) < 2:
        raise ValueError('Not enough rows in data source')
    if layer_defn.GetGeomType() in geometry_types:
        geometry_type = geometry_types.get(layer_defn.GetGeomType(), None)
    elif fieldnames[-3:] == [X_FIELDNAME, Y_FIELDNAME, GEOM_FIELDNAME]:
        geometry = ogr.CreateGeometryFromWkt(data_sample[1][-1])
        geometry_type = geometry_types.get(geometry.GetGeometryType(), None)
    else:
        geometry_type = None
    return (data_sample, geometry_type)

def __init__(self, model: openvino.runtime.Model, parent_model: OVBaseModel, ov_config: Optional[Dict[str, str]]=None, model_name: str='encoder', model_dir: str=None):
    self.model = model
    self.parent_model = parent_model
    self.input_names = {key.get_any_name(): idx for (idx, key) in enumerate(self.model.inputs)}
    self.input_dtype = {inputs.get_any_name(): OV_TO_NP_TYPE[inputs.get_element_type().get_type_name()] for inputs in self.model.inputs}
    self.ov_config = ov_config or {**self.parent_model.ov_config}
    self.request = None
    self._model_name = model_name
    self._model_dir = Path(model_dir or parent_model._model_save_dir)
    config_path = self._model_dir / model_name / self.CONFIG_NAME
    self.config = self.parent_model._dict_from_json_file(config_path) if config_path.is_file() else {}
    if 'CACHE_DIR' not in self.ov_config:
        if 'tmp' in str(self._model_dir):
            pass
        else:
            self.ov_config['CACHE_DIR'] = os.path.join(self._model_dir, self._model_name)

def update(self, **kwargs):
    if self.can_update:
        project_update = self.project_updates.create()
        for (key, value) in kwargs.items():
            setattr(project_update, key, value)
        if hasattr(settings, 'CELERY_UNIT_TEST'):
            project_update.start(None, **kwargs)
        else:
            project_update.signal_start(**kwargs)
        return project_update

def visit_ConstantNode(self, node):
    escaped_value = self.escape_value(node.value)
    self.write("'" + escaped_value + "'")
    def escape_value(self, value):
        return str(value).replace("'", "\'").replace("\", "\\")

def on_task_metainfo(self, task, config):
    for entry in task.entries:
        snapshot = entry.snapshots.get('after_input')
        if not snapshot:
            entry.take_snapshot('after_input')

def next(self):
    if self._stop_iteration:
        raise StopIteration
    elif self._has_saved:
        self._has_saved = False
        saved_object = self._saved
        self._saved = None
        return saved_object
    else:
        return self._generator.next()

def _reset(self):
    self.agentPos = self.startPos
    self.agentDir = 0
    self.stepCount = 0
    self.render()
    return np.array([])

def action_stop_flooding(self):
    self.warning(self._rx_log, 'Stopping flooding')
    self.flooding_active = False

def find_target_size(model_name):
    target_sizes = {'VGG-Face': (224, 224), 'Facenet': (160, 160), 'Facenet512': (160, 160), 'OpenFace': (96, 96), 'DeepFace': (152, 152), 'DeepID': (47, 55), 'Dlib': (150, 150), 'ArcFace': (112, 112), 'SFace': (112, 112)}
    if model_name not in target_sizes.keys():
        raise ValueError(f'unimplemented model name - {model_name}')
    return target_sizes[model_name]

def subset_for(self, selected_asset_keys: AbstractSet[AssetKey]) -> 'AssetsDefinition':
    check.invariant(self.can_subset, f'Attempted to subset AssetsDefinition for {self.node_def.name}, but can_subset=False.')
    filtered_asset_deps = {key: deps for (key, deps) in self._asset_deps.items() if key in selected_asset_keys}
    return AssetsDefinition(keys_by_input_name=self._keys_by_input_name, keys_by_output_name=self._keys_by_output_name, node_def=self.node_def, partitions_def=self.partitions_def, partition_mappings=self._partition_mappings, asset_deps=filtered_asset_deps, can_subset=self.can_subset, selected_asset_keys=selected_asset_keys & self.keys, resource_defs=self.resource_defs, group_names_by_key=self.group_names_by_key)

def update_tool(db: Session, tool: Tool, patch_tool: t.Union[CreateTool, PatchToolDockerimage]) -> Tool:
    if isinstance(patch_tool, CreateTool):
        tool.name = patch_tool.name
    elif patch_tool.persistent:
        tool.docker_image_template = patch_tool.persistent
        tool.is_read_only = True
    db.add(tool)
    db.commit()
    return tool

def tabulate_tensor_comment(self, L, ir):
    comment = f'Tensor with shape {L} and index representation {ir}'
    return comment

def __init__(self, dataDir):
    super(FileSystemBackend, self).__init__()
    self._dataDir = dataDir
    self.load_reference_sets()
    self.load_datasets()

def load_reference_sets(self):
    referencesDirName = 'references'
    referenceSetDir = os.path.join(self._dataDir, referencesDirName)
    for referenceSetName in os.listdir(referenceSetDir):
        relativePath = os.path.join(referenceSetDir, referenceSetName)
        if os.path.isdir(relativePath):
            referenceSet = references.HtslibReferenceSet(referenceSetName, relativePath, self)
            self.addReferenceSet(referenceSet)

def load_datasets(self):
    datasetDirs = [os.path.join(self._dataDir, directory) for directory in os.listdir(self._dataDir) if os.path.isdir(os.path.join(self._dataDir, directory)) and directory != 'references']
    for datasetDir in datasetDirs:
        dataset = datasets.FileSystemDataset(datasetDir, self)
        self.addDataset(dataset)

def render(self, just_html=False):
    if not just_html:
        if self.is_internet_explorer():
            self.headers['Content-Type'] = 'text/html'
            self.xml = None
    return basepage.render(self, just_html)

def _update_job(self, job_id, state=None, **kwargs):
    with self.session_scope() as session:
        try:
            (job, orm_job) = self._get_job_and_orm_job(job_id, session)
            if state is not None:
                orm_job.state = state
            for (kwarg, value) in kwargs.items():
                setattr(orm_job.obj, kwarg, value)
            session.add(orm_job)
            return (orm_job.obj, orm_job)
        except JobNotFound:
            if state:
                logger.error('Tried to update job with id {} with state {} but it was not found'.format(job_id, state))
            else:
                logger.error('Tried to update job with id {} but it was not found'.format(job_id))

def __init__(self, database):
    self.database = database
    self.types = {lltype.Char: 'i8', lltype.Bool: 'i1', lltype.SingleFloat: 'float', lltype.Float: 'double', lltype.UniChar: 'i16', lltype.Void: 'void', lltype.UnsignedLongLong: 'i64', lltype.SignedLongLong: 'i64', llmemory.Address: 'i8*'}
    if sys.maxint == 2 ** 31 - 1:
        self.types.update({lltype.Signed: 'i32', lltype.Unsigned: 'i32'})
    elif sys.maxint == 2 ** 63 - 1:
        self.types.update({lltype.Signed: 'i64', lltype.Unsigned: 'i64'})
    else:
        raise Exception('Unsupported platform - unknown word size')
    self.reprs = {lltype.SignedLongLong: self.repr_signed, lltype.Signed: self.repr_signed, lltype.UnsignedLongLong: self.repr_default, lltype.Unsigned: self.repr_default, lltype.SingleFloat: self.repr_singlefloat, lltype.Float: self.repr_float, lltype.Char: self.repr_char, lltype.UniChar: self.repr_unichar, lltype.Bool: self.repr_bool, lltype.Void: self.repr_void, llmemory.Address: self.repr_address}
    try:
        import ctypes
    except ImportError:
        pass
    else:
        from pypy.rpython.rctypes import rcarithmetic as rcarith
        self.types.update({rcarith.CByte: self.types[lltype.Char], rcarith.CUByte: 'i8', rcarith.CShort: 'i16', rcarith.CUShort: 'i16', rcarith.CInt: 'i32', rcarith.CUInt: 'i32', rcarith.CLong: self.types[lltype.Signed], rcarith.CULong: self.types[lltype.Unsigned], rcarith.CLonglong: self.types[lltype.SignedLongLong], rcarith.CULonglong: self.types[lltype.UnsignedLongLong]})
        self.reprs.update({rcarith.CByte: self.repr_default, rcarith.CUByte: self.repr_default, rcarith.CShort: self.repr_default, rcarith.CUShort: self.repr_default, rcarith.CInt: self.repr_default, rcarith.CUInt: self.repr_default, rcarith.CLong: self.repr_signed, rcarith.CULong: self.repr_default, rcarith.CLonglong: self.repr_signed, rcarith.CULonglong: self.repr_default})

def _generateColumnHeader(self, obj, **args):
    result = []
    try:
        role = args.get('role', obj.getRole())
    except:
        role = None
    if role in [pyatspi.ROLE_COLUMN_HEADER, pyatspi.ROLE_TABLE_COLUMN_HEADER]:
        return result
    try:
        table = obj.parent.queryTable()
    except:
        pass
    else:
        index = self._script.utilities.cellIndex(obj)
        columnIndex = table.getColumnAtIndex(index)
        if columnIndex >= 0:
            header = table.getColumnHeader(columnIndex)
            if header:
                desc = self._script.utilities.displayedText(header)
                if desc and len(desc):
                    text = desc
                    if args['mode'] == 'speech':
                        if settings.speechVerbosityLevel == settings.VERBOSITY_LEVEL_VERBOSE and (not args.get('formatType', None) in ['basicWhereAmI', 'detailedWhereAmI']):
                            text = desc + ' ' + self.getLocalizedRoleName(obj, pyatspi.ROLE_COLUMN_HEADER)
                    elif args['mode'] == 'braille':
                        text = desc + ' ' + self.getLocalizedRoleName(obj, pyatspi.ROLE_COLUMN_HEADER)
                    result.append(text)
    return result

def get_sequence(self, name):
    if name in self.saved_sequences:
        with open(self.sequence_dir + name + '.seq', 'rb') as infile:
            sequence = pickle.load(infile)
    else:
        raise ValueError('Error: No sequence with name "' + name + '" in saved sequences.')
    return sequence

def __str__(self):
    modifiers = ' '.join(self.type_modifiers)
    syntax = ''
    if self.reference:
        syntax += '&'
    if self.pointer:
        syntax += '*'
    templated_types = '<%s>' % ', '.join(self.templated_types) if self.templated_types else ''
    suffix = '%s %s%s %s%s' % (modifiers, self.type_name, syntax, self.name, templated_types)
    if self.default:
        suffix += ' = ' + self.default
    return self._StringHelper(self.__class__.__name__, suffix)

def SBROM_KeyDerivation(self, aeskeytype, key, salt, requestedlen, destaddr):
    result = bytearray()
    buffer = bytearray(b'\x00' * 67)
    if aeskeytype - 1 > 4 or 1 << aeskeytype - 1 & 23 == 0:
        return 4060086274
    if requestedlen > 255 or requestedlen << 28 & 4294967295:
        return 4060086275
    if 0 >= len(key) > 32:
        return 4060086275
    bufferlen = len(salt) + 3 + len(key)
    iterlength = requestedlen + 15 >> 4
    if len(key) == 0:
        keyend = 1
    else:
        buffer[1:1 + len(key)] = key
        keyend = len(key) + 1
    saltstart = keyend + 1
    if len(salt) > 0:
        buffer[saltstart:saltstart + len(salt)] = salt
    buffer[saltstart + len(salt):saltstart + len(salt) + 4] = pack('<I', 8 * requestedlen)
    if len(buffer) < bufferlen:
        return 4060086276
    for i in range(0, iterlength):
        buffer[0] = i + 1
        dstaddr = self.SBROM_AesCmac(aeskeytype, 0, buffer, 0, bufferlen, destaddr)
        if dstaddr != 0:
            for field in self.read32(dstaddr + 264, 4):
                result.extend(pack('<I', field))
    return result

def decrypt(self):
    expected_context = self.parameters.get('ExpectedEncryptionContext')
    actual_context = self.parameters.get('EncryptionContext')
    if expected_context != actual_context:
        raise ValueError('EncryptionContext does not match. Refusing to decode.')
    value = self.parameters.get('CiphertextBlob')
    try:
        return json.dumps({'Plaintext': base64.b64decode(value).decode('utf-8'), 'KeyId': 'key_id'})
    except UnicodeDecodeError:
        return json.dumps({'Plaintext': value})

