def numpy_elu(x: numpy.ndarray, /, *, alpha: float=1) -> numpy.ndarray:
    return numpy.where(x > 0, x, alpha * (numpy.exp(x) - 1))

def _present_prompt_and_evaluate_user_input(self, include_chevron=True):
    self._load_prompt_string()
    self._current_prompt_is_done = False
    while not self._current_prompt_is_done:
        prompt_string = self._prompt_strings[-1]
        prompt_string = self._indent_and_number_prompt_string(prompt_string)
        default_value = str(self._current_prompt.default_value)
        include_chevron = self._current_prompt.include_chevron
        user_input = self._io_manager.handle_user_input(prompt_string, default_value=default_value, include_chevron=include_chevron, include_newline=self.include_newlines, prompt_character=self.prompt_character, capitalize_prompt=self.capitalize_prompts)
        if user_input is None:
            self._prompt_index += 1
            break
        directive = self._io_manager._handle_io_manager_directive(user_input)
        if self._should_backtrack():
            self._current_prompt_is_done = True
            self._all_prompts_are_done = True
        elif directive is None:
            continue
        elif directive == 'help':
            self._display_help()
        elif directive == 'previous':
            self._move_to_previous_prompt()
            break
        elif directive == 'skip':
            break
        elif isinstance(directive, str):
            self._evaluate_user_input(directive)
        else:
            self._io_manager.print_not_yet_implemented()

def method(self, handle, methodName, args, subtypes, addr, userId):
    self.log.debug('Method called: name = %s \n args = %s \n handle = %s \n addr = %s \n subtypes = %s \n userId = %s', methodName, args, handle, addr, subtypes, userId)
    try:
        if addr == self.image_factory_addr:
            target_obj = self.image_factory
        elif repr(addr) in self.managedObjects:
            target_obj = self.managedObjects[repr(addr)]
        else:
            raise RuntimeError('%s does not match an object managed by ImageFactoryAgent!  Unable to respond to %s.' % (repr(addr), methodName))
        result = getattr(target_obj, methodName)(**args)
        if addr == self.image_factory_addr and methodName in ('image', 'provider_image'):
            build_adaptor_instance_name = 'build_adaptor:%s:%s' % (methodName, result.builder.image_id)
            qmf_object_addr = self.session.addData(result.qmf_object, build_adaptor_instance_name, persistent=True)
            self.managedObjects[repr(qmf_object_addr)] = result
            handle.addReturnArgument('build_adaptor', qmf_object_addr.asMap())
            self.session.methodSuccess(handle)
        elif result and isinstance(result, dict):
            for key in result:
                handle.addReturnArgument(key, result[key])
            self.session.methodSuccess(handle)
        else:
            returned_dictionary = {}
            for method in type(target_obj).qmf_schema.getMethods():
                if method.getName() == methodName:
                    for method_arg in method.getArguments():
                        if method_arg.getDirection() == DIR_OUT:
                            returned_dictionary.update({method_arg.getName(): method_arg.getDesc()})
            raise RuntimeError("Method '%s' on objects of class %s must return a dictionary of %s" % (methodName, target_obj.__class__.__name__, returned_dictionary))
    except Exception as e:
        self.log.exception(str(e))
        self.session.raiseException(handle, str(e))

def register_length(self) -> int | None:
    for key in self._data:
        if key == '':
            continue
        return self[key].shape[0]
    return None

def execute(self, *args):
    valid = EssentialParameters(self.__class__.__name__, [self._src_dir, self._src_pattern, self._format, self._dest_name])
    valid()
    files = super().get_target_files(self._src_dir, self._src_pattern)
    self.check_file_existence(files)
    dir = self._dest_dir if self._dest_dir is not None else self._src_dir
    dest_path = os.path.join(dir, self._dest_name + '.%s' % self._format)
    if self._format == 'tar':
        with tarfile.open(dest_path, 'w') as tar:
            for file in files:
                arcname = os.path.join(self._dest_name, os.path.basename(file)) if self._create_dir else os.path.basename(file)
                tar.add(file, arcname=arcname)
    elif self._format == 'zip':
        with zipfile.ZipFile(dest_path, 'w') as zp:
            for file in files:
                arcname = os.path.join(self._dest_name, os.path.basename(file)) if self._create_dir else os.path.basename(file)
                zp.write(file, arcname=arcname)
    else:
        raise InvalidParameter("'format' must set one of the followings [tar, zip]")

