class P11CryptoPluginException(Exception):
    pass

class NotableErrorA(P11CryptoPluginException):
    pass

class NotableErrorB(P11CryptoPluginException):
    pass

class NotableErrorC(P11CryptoPluginException):
    pass

def _check_error(self, value):
    if value != CKR_OK:
        if value == ERROR_CODE_A:
            raise NotableErrorA(u._('Specific error A occurred: {hex_value} {code}').format(hex_value=hex(value), code=ERROR_CODES.get(value, 'CKR_????')))
        elif value == ERROR_CODE_B:
            raise NotableErrorB(u._('Specific error B occurred: {hex_value} {code}').format(hex_value=hex(value), code=ERROR_CODES.get(value, 'CKR_????')))
        elif value == ERROR_CODE_C:
            raise NotableErrorC(u._('Specific error C occurred: {hex_value} {code}').format(hex_value=hex(value), code=ERROR_CODES.get(value, 'CKR_????')))
        else:
            raise P11CryptoPluginException(u._('HSM returned response code: {hex_value} {code}').format(hex_value=hex(value), code=ERROR_CODES.get(value, 'CKR_????')))

def setitem_from_path(self, path, value, trans=None):
    (path, item) = (path[:-1], path[-1])
    struct = self.struct
    for p in range(len(path)):
        part = path[p]
        if part.startswith('['):
            struct = struct[eval(part[1:-1])]
        else:
            struct = struct[part]
        if struct is None:
            return
    if isinstance(struct, HandleClass):
        setattr(struct, item, value)
    elif isinstance(struct, (list, tuple)):
        pos = int(item)
        if pos < len(struct):
            struct[int(item)] = value
    elif isinstance(struct, dict):
        if item in struct.keys():
            struct[item] = value
    elif hasattr(struct, item):
        setattr(struct, item, value)
    else:
        return
    self.update_db(trans)

