def _save_export_countries(self, interaction, validated_export_countries):
    existing_country_mapping = {export_country.country: export_country for export_country in interaction.export_countries.all()}
    new_country_mapping = {item['country']: item for item in validated_export_countries}
    for (new_country, export_data) in new_country_mapping.items():
        status = export_data['status']
        if new_country in existing_country_mapping:
            existing_country = existing_country_mapping[new_country]
            existing_country.status = status
            existing_country.save()
        else:
            InteractionExportCountry.objects.create(country=new_country, interaction=interaction, status=status, created_by=interaction.created_by)
        current_date = now()
        record_date = current_date if interaction.date > current_date else interaction.date
        interaction.company.add_export_country(new_country, status, record_date, interaction.created_by)

def registeropt(self, name, valuetype, where, default):
    for opt in self.opts:
        if opt[0] == name:
            raise ValueError(f'Option name "{name}" is already registered.')
    self.opts.append((name, valuetype, where, default))

def announce(self, negotiated, nlris=None, mps=None):
    asn4 = negotiated.asn4
    local_as = negotiated.local_as
    peer_as = negotiated.peer_as
    msg_size = negotiated.msg_size
    attr = self.attributes.pack(asn4, local_as, peer_as)
    if nlris is None and mps is None:
        packed_nlri = []
        packed_mp = []
        for nlri in self.nlris:
            (afi, safi) = (nlri.afi, nlri.safi)
            addpath = negotiated.addpath.send(afi, safi)
            if nlri.family() in negotiated.families:
                if afi == AFI.ipv4 and safi in [SAFI.unicast, SAFI.multicast] and (nlri.nexthop == self.attributes.get(AID.NEXT_HOP, None)):
                    packed_nlri.append(nlri)
                else:
                    packed_mp.append(nlri)
    else:
        packed_nlri = nlris
        packed_mp = mps
    if not packed_nlri and (not packed_mp):
        return ''
    return [_ for _ in self.make_message(msg_size, attr, MPRNLRI(packed_mp).pack(addpath), ''.join((nlri.pack(addpath) for nlri in packed_nlri)))]

def deleteBlocks(self):
    logging.info('Starting deleteBlocks methods')
    for block in self.blocks:
        if block.has_active_subscription():
            block.deleted = 2
            logging.info(f'Block {block.id} has an active subscription, marked as deleted=2')
        elif block.transfer_finished():
            self.request_block_deletion(block)
            block.deleted = 1
            logging.info(f'Block {block.id} transfer finished, requested deletion and marked as deleted=1')
        else:
            logging.info(f'Block {block.id} cannot be deleted yet, checking next cycle')

def _call_series(self, series):
    level = getattr(self, 'level', None)
    axis = getattr(self, 'axis', None)
    skipna = getattr(self, 'skipna', None)
    numeric_only = getattr(self, 'numeric_only', None)
    bool_only = getattr(self, 'bool_only', None)
    if axis == 'index':
        axis = 0
    self._axis = axis
    if level is not None:
        if hasattr(self, 'groupby') and self.groupby is not None:
            pass
        else:
            raise NotImplementedError('Not support specified level now')
    empty_series = build_series(series)
    func_name = getattr(self, '_func_name')
    if func_name == 'count':
        reduced_series = empty_series.count(level=level)
    elif func_name == 'nunique':
        reduced_series = empty_series.nunique()
    elif func_name in ('all', 'any'):
        reduced_series = getattr(empty_series, func_name)(axis=axis, level=level, bool_only=bool_only)
    elif func_name == 'size':
        reduced_series = empty_series.size
    elif func_name == 'custom_reduction':
        reduced_series = getattr(self, 'custom_reduction').__call_agg__(empty_series)
    elif func_name == 'str_concat':
        reduced_series = pd.Series([empty_series.str.cat(**getattr(self, 'get_reduction_args')())])
    else:
        reduced_series = getattr(empty_series, func_name)(axis=axis, level=level, skipna=skipna, numeric_only=numeric_only)
    return self.new_scalar([series], dtype=np.array(reduced_series).dtype)

import os
import shutil
import fnmatch

class LocalTransport:

    def copy(self, source, destination, dereference=False, pattern=None):
        if not source:
            raise ValueError('Input source to copy must be a non empty object')
        if not destination:
            raise ValueError('Input destination to copy must be a non empty object')
        if not os.path.exists(os.path.join(self.curdir, source)):
            raise OSError('Source not found')
        if self.normalize(source) == self.normalize(destination):
            raise ValueError('Cannot copy from itself to itself')
        if self.isfile(destination) or self.isdir(destination):
            self.rmtree(destination)
        if pattern:
            file_list = self.listdir(source)
            to_copy = [os.path.join(source, i) for i in file_list if fnmatch.fnmatch(i, pattern)]
            to_copy_to = [os.path.join(destination, i) for i in file_list if fnmatch.fnmatch(i, pattern)]
            for (this_src, this_dst) in zip(to_copy, to_copy_to):
                splitted_list = self._os_path_split_asunder(this_dst)
                does_dir_exist = ''
                for this_dir in splitted_list[:-1]:
                    does_dir_exist = os.path.join(does_dir_exist, this_dir)
                    try:
                        self.mkdir(does_dir_exist)
                    except OSError as e:
                        if 'File exists' in e.message:
                            pass
                if self.isdir(this_src):
                    self.copytree(this_src, this_dst, dereference)
                else:
                    self.copyfile(this_src, this_dst)
        elif self.isdir(source):
            return self.copytree(source, destination, dereference)
        else:
            return self.copyfile(source, destination)

def prepare_state(self, src_tokens: Tensor, *, prefix_tokens: Optional[Tensor]=None) -> BeamSearchState:
    (bsz, src_len) = src_tokens.size()[:2]
    beam_size = self.beam_size
    max_len = min(self.max_len, 2 * src_len + 10)
    order = torch.arange(bsz, dtype=torch.int64, device=src_tokens.device).view(-1, 1).repeat(1, beam_size).view(-1)
    scores = torch.zeros(size=(bsz * beam_size, max_len + 2), dtype=torch.float32, device=src_tokens.device)
    tokens = torch.full(size=(bsz * beam_size, max_len + 2), fill_value=self.tokenizer.PAD, dtype=torch.long, device=src_tokens.device)
    if prefix_tokens is not None:
        if prefix_tokens.size(0) != bsz:
            raise ValueError('prefix_tokens must have the same number of elements as the batch size')
        tokens[:, 0] = prefix_tokens.T[0].view(-1, 1).repeat(1, beam_size).view(-1)
    else:
        tokens[:, 0] = self.tokenizer.BOS
    finished_mask = torch.zeros(size=(bsz, beam_size), dtype=torch.bool, device=src_tokens.device)
    return BeamSearchState(max_len=max_len, tokens=tokens, scores=scores, finished_mask=finished_mask, order=order, step=0)

def test_dhcp_start_no_dhcp_end(self):
    self.conf.config(dhcp_start='192.168.24.10', dhcp_end=[], group='ctlplane-subnet')
