def _get_step_view_from_execution(self, execution: proto.Execution) -> StepView:
    step_name = self.step_type_mapping[execution.type_id]
    if step_name.startswith(BASE_STEP_PREFIX):
        step_name = step_name[len(BASE_STEP_PREFIX):]
    step_parameters = {k: json.loads(v.string_value) for (k, v) in execution.custom_properties.items()}
