def purestr(x):
    if not isinstance(x, Basic):
        return str(x)
    return srepr(x)

def draw(self, graph, name='Network from igraph', *args, **kwds):
    cy = self.service
    network_id = cy.createNetwork(name)
    self.network_id = network_id
    node_ids = [str(idx) for idx in range(graph.vcount())]
    cy.createNodes(network_id, node_ids)
    edgelists = [[], []]
    for (v1, v2) in graph.get_edgelist():
        edgelists[0].append(node_ids[v1])
        edgelists[1].append(node_ids[v2])
    edge_ids = cy.createEdges(network_id, edgelists[0], edgelists[1], ['unknown'] * graph.ecount(), [graph.is_directed()] * graph.ecount(), False)
    if 'layout' in kwds:
        layout = self.ensure_layout(kwds['layout'], graph)
        cy.applyLayout(network_id, layout)
    cy.performDefaultLayout(network_id)
    try:
        attr_names = set(cy.getNetworkAttributeNames())
    except Exception:
        attr_names = set()
    for attr in graph.attributes():
        (cy_type, value) = self.infer_cytoscape_type([graph[attr]])
        value = value[0]
        if value is None:
            continue
        try:
            while attr in attr_names and cy.getNetworkAttributeType(attr) != cy_type:
                attr += '_'
            cy.addNetworkAttributes(attr, cy_type, {network_id: value})
        except Exception:
            pass
    attr_names = set(cy.getNodeAttributeNames())
    for attr in graph.vertex_attributes():
        (cy_type, values) = self.infer_cytoscape_type(graph.vs[attr])
        values = dict((pair for pair in zip(node_ids, values) if pair[1] is not None))
        while attr in attr_names and cy.getNodeAttributeType(attr) != cy_type:
            attr += '_'
        cy.addNodeAttributes(attr, cy_type, values, True)
    attr_names = set(cy.getEdgeAttributeNames())
    for attr in graph.edge_attributes():
        (cy_type, values) = self.infer_cytoscape_type(graph.es[attr])
        values = dict((pair for pair in zip(edge_ids, values) if pair[1] is not None))
        while attr in attr_names and cy.getEdgeAttributeType(attr) != cy_type:
            attr += '_'
        cy.addEdgeAttributes(attr, cy_type, values)

def __gpt_labeldisk(self, type, devname, label=''):
    self.__system('dd if=/dev/zero of=/dev/%s bs=1m count=1' % devname)
    self.__system("dd if=/dev/zero of=/dev/%s bs=1m oseek=`diskinfo %s | awk '{print ($3 / (1024*1024)) - 3;}'`" % (devname, devname))
    self.__system('dd if=/dev/zero of=/dev/%s bs=4096 count=1' % devname)
    self.__system("dd if=/dev/zero of=/dev/%s bs=4096 oseek=`diskinfo %s | awk '{print ($3 / (4096)) - 3;}'`" % (devname, devname))
    if label != '':
        self.__system('gpart create -s gpt /dev/%s && gpart add -t %s -l %s %s' % (devname, type, label, devname))
    else:
        self.__system('gpart create -s gpt /dev/%s && gpart add -t %s %s' % (devname, type, devname))

def __new__(cls, class_name, bases, class_dict):
    names = []
    names_with_refs = []
    includes = {}
    removes = []
    for (name, prop) in class_dict.items():
        if not isinstance(prop, Include):
            continue
        delegate = prop._delegate
        if not (isinstance(delegate, type) and issubclass(delegate, PropertyGroup)):
            continue
        if prop._prefix is None:
            prefix = name + '_'
        else:
            prefix = prop._prefix + '_'
        for subpropname in dir(delegate):
            if subpropname.startswith('__'):
                continue
            fullpropname = prefix + subpropname
            subprop = getattr(delegate, subpropname)
            if isinstance(subprop, BaseProperty):
                subprop = copy(subprop)
            includes[fullpropname] = subprop
        removes.append(name)
    for (key, val) in includes.items():
        if key not in class_dict:
            class_dict[key] = val
    for tmp in removes:
        del class_dict[tmp]
    for (name, prop) in class_dict.items():
        if isinstance(prop, BaseProperty):
            prop.name = name
            if hasattr(prop, 'has_ref') and prop.has_ref:
                names_with_refs.append(name)
            names.append(name)
        elif isinstance(prop, type) and issubclass(prop, BaseProperty):
            newprop = prop.autocreate(name=name)
            class_dict[name] = newprop
            newprop.name = name
            names.append(name)
    class_dict['__properties__'] = names
    class_dict['__properties_with_refs__'] = names_with_refs
    return type.__new__(cls, class_name, bases, class_dict)

