def getRHSDeriv(self, tInd, src, v, adjoint=False):
    C = self.mesh.edgeCurl
    MeSigmaI = self.MeSigmaI

    def MeSigmaIDeriv(u):
        return self.MeSigmaIDeriv(u)
    MfMui = self.MfMui
    (_, s_e) = src.eval(self, self.times[tInd])
    (s_mDeriv, s_eDeriv) = src.evalDeriv(self, self.times[tInd], adjoint=adjoint)
    if adjoint:
        if self._makeASymmetric is True:
            v = self.MfMui * v
        MeSigmaIDerivT_v = MeSigmaIDeriv(s_e).T * C.T * v if not isinstance(s_e, Utils.Zero) else Utils.Zero()
        RHSDeriv = MeSigmaIDerivT_v + s_eDeriv(MeSigmaI.T * (C.T * v)) + s_mDeriv(v)
        return RHSDeriv
    MeSigmaIDeriv_v = MeSigmaIDeriv(s_e) * v if not isinstance(s_e, Utils.Zero) else Utils.Zero()
    temp = MeSigmaIDeriv_v + MeSigmaI * s_eDeriv(v) + s_mDeriv(v)
    RHSDeriv = C * temp.astype(float) if not isinstance(temp, Utils.Zero) else C * temp
    if self._makeASymmetric is True:
        return self.MfMui.T * RHSDeriv
    return RHSDeriv

