def __eq__(self, other: object) -> bool:
    if not isinstance(other, Matrix):
        raise TypeError('Matrix class required.')
    if self.shape != other.shape:
        raise TypeError('Matrices have different shapes.')
    return np.allclose(self.matrix, other.matrix, atol=self.abs_tol)

def _get_data(self):
    try:
        data = self.connection.recv(4)
        if not data:
            time.sleep(1e-06)
            return self._get_data()
        length = int.from_bytes(data, 'little')
        chunks = []
        while len(chunks) < length:
            chunk = self.connection.recv(length - len(chunks))
            if not chunk:
                break
            chunks.append(chunk.decode())
        return ''.join(chunks)
    except socket.timeout as e:
        print('env timed out', e)
    return None

def gen(self, n: int, bounds: List[Tuple[float, float]], objective_weights: Tensor, outcome_constraints: Optional[Tuple[Tensor, Tensor]]=None, linear_constraints: Optional[Tuple[Tensor, Tensor]]=None, fixed_features: Optional[Dict[int, float]]=None, pending_observations: Optional[List[Tensor]]=None, model_gen_options: Optional[TConfig]=None, rounding_func: Optional[Callable[[Tensor], Tensor]]=None, target_fidelities: Optional[Dict[int, float]]=None) -> Tuple[Tensor, Tensor, TGenMetadata, List[Optional[Dict[str, typing.Any]]]]:
    for b in bounds:
        assert b == (-1, 1)
    assert linear_constraints is None
    assert fixed_features is None
    assert pending_observations is None
    A = torch.cat((self.Binv, -self.Binv))
    b = torch.ones(2 * self.Binv.shape[0], 1, dtype=self.dtype, device=self.device)
    linear_constraints = (A, b)
    noiseless = max((Yvar.min().item() for Yvar in self.Yvars)) < 1e-05
    if model_gen_options is None:
        model_gen_options = {}
    model_gen_options = {'acquisition_function_kwargs': {'q': n, 'noiseless': noiseless}, 'optimizer_kwargs': {'raw_samples': model_gen_options.get('raw_samples', 1000), 'num_restarts': model_gen_options.get('num_restarts', 10), 'B': self.B}}
    (Xd_opt, w, gen_metadata, candidate_metadata) = super().gen(n=n, bounds=[(-100000000.0, 100000000.0)] * self.B.shape[0], objective_weights=objective_weights, outcome_constraints=outcome_constraints, linear_constraints=linear_constraints, model_gen_options=model_gen_options)
    Xopt = (self.Binv @ Xd_opt.t()).t()
    if Xopt.min() < -1 or Xopt.max() > 1:
        logger.debug(f'Clipping from [{Xopt.min()}, {Xopt.max()}]')
        Xopt = torch.clamp(Xopt, min=-1.0, max=1.0)
    return (Xopt, w, gen_metadata, candidate_metadata if candidate_metadata is not None else [])

def get(self, sess_id):
    user = self.request.remote_user or '@public'
    session = self.app.db.sessions.find_one({'_id': bson.objectid.ObjectId(sess_id)})
    if not session:
        self.abort(404)
    experiment = self.app.db.experiments.find_one({'_id': bson.objectid.ObjectId(session['experiment'])})
    if not experiment:
        self.abort(500)
    if user not in experiment['permissions']:
        self.abort(403)
    query = {'session': bson.objectid.ObjectId(sess_id)}
    projection = ['timestamp', 'series', 'acquisition', 'description', 'datatype']
    epochs = list(self.app.db.epochs.find(query, projection))
    self.response.write(json.dumps(epochs, default=bson.json_util.default))

def infer_type(self, expr: E.Apply) -> T.Base:
    if len(expr.arguments) != 1:
        raise Error.WrongArity(expr, 1)
    if not isinstance(expr.arguments[0].type, T.Array) or (expr.arguments[0]._check_quant and expr.arguments[0].type.optional):
        raise Error.StaticTypeMismatch(expr.arguments[0], T.Array(T.Any()), expr.arguments[0].type)
    if isinstance(expr.arguments[0].type.item_type, T.Any):
        raise Error.IndeterminateTypeError(expr.arguments[0])
    ty = expr.arguments[0].type.item_type
    assert isinstance(ty, T.Base)
    return ty.copy(optional=False)

class SpectrumStats(ObservationStats):

    def __init__(self, n_on, n_off, a_on, a_off, obs_id, livetime, spectrum_info):
        super().__init__(n_on, n_off, a_on, a_off, obs_id, livetime)
        self.spectrum_info = spectrum_info

def total_stats(self):
    kwargs = dict(n_on=int(self.on_vector.total_counts.value), n_off=int(self.off_vector.total_counts.value), a_on=np.mean(self.on_vector.backscal), a_off=np.mean(self.off_vector.backscal), obs_id=self.obs_id, livetime=self.livetime, spectrum_info=self.get_spectrum_info())
    return SpectrumStats(**kwargs)

def _purchase_service_create(self, quantity=False):
    PurchaseOrder = self.env['purchase.order']
    supplier_po_map = {}
    sale_line_purchase_map = {}
    for line in self:
        line = line.with_company(line.company_id)
        supplierinfo = line.product_id._select_seller(line)
        if not supplierinfo:
            raise UserError(_('There is no vendor associated to the product %s. Please define a vendor for this product.') % (line.product_id.display_name,))
        partner_supplier = supplierinfo.name
        purchase_order = supplier_po_map.get(partner_supplier.id)
        if not purchase_order:
            purchase_order = PurchaseOrder.search([('partner_id', '=', partner_supplier.id), ('state', '=', 'draft'), ('company_id', '=', line.company_id.id)], limit=1)
        if not purchase_order:
            values = line._purchase_service_prepare_order_values(supplierinfo)
            purchase_order = PurchaseOrder.create(values)
        else:
            so_name = line.order_id.name
            origins = []
            if purchase_order.origin:
                origins = purchase_order.origin.split(', ') + origins
            if so_name not in origins:
                origins += [so_name]
                purchase_order.write({'origin': ', '.join(origins)})
        supplier_po_map[partner_supplier.id] = purchase_order
        values = line._purchase_service_prepare_line_values(purchase_order, quantity=quantity)
        purchase_line = line.env['purchase.order.line'].create(values)
        sale_line_purchase_map.setdefault(line, line.env['purchase.order.line'])
        sale_line_purchase_map[line] |= purchase_line
    return sale_line_purchase_map

import json
