def maintain_process_mapping(self):
    import time, subprocess
    while self.device.is_connected:
        ps_out = subprocess.check_output(['adb', 'shell', 'ps']).decode('utf-8')
        self.pid2uid = {}
        self.pid2name = {}
        for line in ps_out.splitlines()[1:]:
            parts = line.split()
            if len(parts) >= 9:
                uid = parts[1]
                pid = parts[0]
                name = ' '.join(parts[8:])
                self.pid2uid[pid] = uid
                self.pid2name[pid] = name
        time.sleep(1)

def zeros_like(a, dtype=None, order='C'):
    if dtype is None:
        dtype = a.dtype
    a = cupy.ndarray(a.shape, dtype, order=order)
    a.data.memset_async(0, a.nbytes)
    return a

def _call(self, method, *args, **kwargs):
    tid = self._tid.next()
    msg = {'method': method, 'params': list(args)}
    is_notify = '_notify' in kwargs
    if not is_notify:
        msg['id'] = tid
    msg = json.dumps(msg)
    for timeout in self._service.iter_rpc_retry_timeout():
        services = self._service.resolve_service(self._service_name)
        if not services:
            raise RPCError('Service not found')
        for svc in services:
            client = tornado.httpclient.AsyncHTTPClient()
            try:
                response = (yield client.fetch('http://%s/api/%s/' % (svc, self._api), method='POST', body=msg))
            except tornado.httpclient.HTTPError as why:
                if why.code != 499:
                    raise RPCError('RPC Call Failed: %s', why)
                else:
                    self._service.logger.info('Service is not available at %s. Retrying', svc)
                    continue
            except tornado.netutil.ConnectionRefusedError as why:
                self._service.logger.error('Connection refused when trying to reach %s: %s', svc, why)
                break
            except Exception as why:
                raise RPCError('RPC Call Failed: %s' % why)
            if not is_notify:
                result = json.loads(response.body)
                if result.get('error'):
                    raise RPCError('RPC Call Failed: %s' % result['error'])
                else:
                    raise tornado.gen.Return(result['result'])
        self._service.logger.info('All services are not available. Waiting %s seconds')
        yield tornado.gen.sleep(timeout)

def _passthru(http_methods, method=None, async_call=None, driver_passthru=False, description=None, attach=False, require_exclusive_lock=True):
    if async_call is None:
        async_call = True

    def handle_passthru(func):
        api_method = method
        if api_method is None:
            api_method = func.__name__
        supported_ = [i.upper() for i in http_methods]
        description_ = description or ''
        metadata = VendorMetadata(api_method, {'http_methods': supported_, 'async': async_call, 'description': description_, 'attach': attach})
        if driver_passthru:
            func._driver_metadata = metadata
        else:
            metadata[1]['require_exclusive_lock'] = require_exclusive_lock
            func._vendor_metadata = metadata
        passthru_logmessage = 'vendor_passthru failed with method %s'

        @six.wraps(func)
        def passthru_handler(*args, **kwargs):
            try:
                return func(*args, **kwargs)
            except exception.IronicException as e:
                with excutils.save_and_reraise_exception():
                    LOG.exception(passthru_logmessage, api_method)
            except Exception as e:
                LOG.exception(passthru_logmessage, api_method)
                raise exception.VendorPassthruException(message=e)
        return passthru_handler
    return handle_passthru

def certreport(md, t, name, args, id, expiration_threshold=864000):
    try:
        from OpenSSL import crypto
    except ImportError as ex:
        logging.error('certreport requires pyOpenSSL')
        return t
    if t is None:
        raise ValueError('Your plumbing is missing a select statement.')
    seen = {}
    for eid in t.xpath('//md:EntityDescriptor/@entityID', namespaces=NS):
        for cd in t.xpath("md:EntityDescriptor[@entityID='%s']//ds:X509Certificate" % eid, namespaces=NS):
            try:
                cert_pem = cd.text
                cert_der = base64.b64decode(cert_pem)
                m = hashlib.sha1()
                m.update(cert_der)
                fp = m.hexdigest()
                if not seen.get(fp, False):
                    seen[fp] = True
                    cert = crypto.load_certificate(crypto.FILETYPE_ASN1, cert_der)
                    et = datetime.strptime(cert.get_notAfter(), '%Y%m%d%H%M%SZ')
                    now = datetime.now()
                    dt = et - now
                    if dt.total_seconds() < 0:
                        e = cd.getparent().getparent().getparent().getparent().getparent()
                        md.annotate(e, 'certificate-error', 'certificate has expired', '%s expired %s ago' % (_subject(cert), -dt))
                        logging.error('%s expired %s ago' % (eid, -dt))
                    elif dt.total_seconds() < expiration_threshold:
                        e = cd.getparent().getparent().getparent().getparent().getparent()
                        print(e)
                        md.annotate(e, 'certificate-warning', 'certificate about to expire', '%s expires in %s' % (_subject(cert), dt))
                        logging.warn('%s expires in %s' % (eid, dt))
            except Exception as ex:
                logging.error(ex)

def set_signature(name, **kwargs):
    user = kwargs['user']
    data = request.json
    if 'name' in data and name != data['name']:
        return make_api_response({'success': False}, 'You cannot change the tagcheck signature name', 400)
    if not is_valid_status(data, user):
        return make_api_response('', 'Only admins are allowed to deploy or disable signatures', 403)
    sig = STORAGE.tc_signature.get(name, as_obj=False)
    if sig:
        if sig.get('status') == 'DEPLOYED' and 'status' in data:
            return make_api_response({'success': False}, 'Cannot change status of a deployed signature', 400)
        sig.update(data)
        return make_api_response({'success': STORAGE.tc_signature.save(name, sig)})
    else:
        return make_api_response({'success': False}, 'Signature does not exist', 404)

import numpy as np

def get_list_shape(xs):
    shape = [len(xs)]
    for (i, x) in enumerate(xs):
        if isinstance(x, list):
            if len(shape) == 1:
                shape.append(0)
            shape[1] = max(len(x), shape[1])
            for (j, y) in enumerate(x):
                if isinstance(y, list):
                    if len(shape) == 2:
                        shape.append(0)
                    shape[2] = max(len(y), shape[2])
                    for (k, z) in enumerate(y):
                        if isinstance(z, list):
                            if len(shape) == 3:
                                shape.append(0)
                            shape[3] = max(len(z), shape[3])
    return shape

def numpify(xs, pad=0, keys=None, dtypes=None):
    is_dict = isinstance(xs, dict)
    xs_np = {} if is_dict else [0] * len(xs)
    xs_iter = xs.items() if is_dict else enumerate(xs)
    for (i, (key, x)) in enumerate(xs_iter):
        if keys is None or key in keys:
            shape = get_list_shape(x)
            if dtypes is None:
                dtype = np.int64
            else:
                dtype = dtypes[i]
            x_np = np.full(shape, pad, dtype)
            dims = len(shape)
            if dims == 0:
                x_np = x
            elif dims == 1:
                x_np[0:shape[0]] = x
            elif dims == 2:
                for (j, y) in enumerate(x):
                    x_np[j, 0:len(y)] = [ys for ys in y]
            elif dims == 3:
                for (j, ys) in enumerate(x):
                    for (k, y) in enumerate(ys):
                        x_np[j, k, 0:len(y)] = y
            elif dims > 3:
                flat_x = np.array(x).flatten()
                x_np = flat_x.reshape(shape)
            else:
                raise NotImplementedError
            xs_np[key] = x_np
        else:
            xs_np[key] = x
    return xs_np

import asyncio
import os.path

class Package:

    def __init__(self, name, serial, mirror):
        self.name = name
        self.serial = serial
        self.mirror = mirror
        self.releases = package_info.json()['releases']

    async def download_file(self, url, sha256sum):
        path = self._file_url_to_local_path(url)
        if os.path.exists(path):
            existing_hash = utils.hash(path)
            if existing_hash == sha256sum:
                return None
            else:
                logger.info('Checksum mismatch with local file, downloading again.')
        return path

    async def sync_release_files(self):
        release_files = []
        for release in self.releases.values():
            release_files.extend(release)
        downloaded_files = set()
        tasks = []
        for release_file in release_files:
            tasks.append(self.download_file(release_file['url'], release_file['digests']['sha256']))
        downloaded_results = await asyncio.gather(*tasks, return_exceptions=True)
        deferred_exception = None
        for (result, release_file) in zip(downloaded_results, release_files):
            if isinstance(result, Exception):
                logger.exception(f"Continuing to next file after error downloading: {release_file['url']}")
                if not deferred_exception:
                    deferred_exception = result
            else:
                downloaded_files.add(str(result.relative_to(self.mirror.homedir)))
        if deferred_exception:
            raise deferred_exception
        self.mirror.altered_packages[self.name] = downloaded_files

def call_api(self, api_client: API, session: Session) -> str:
    try:
        source_sdk_object = sdclientapi.Source(uuid=self.source_uuid)
        api_client.delete_source(source_sdk_object, timeout=5)
        return self.source_uuid
    except (RequestTimeoutError, ServerConnectionError):
        raise
    except Exception as e:
        error_message = 'Failed to delete source {uuid} due to {exception}'.format(uuid=self.source_uuid, exception=repr(e))
        raise DeleteSourceJobException(error_message, self.source_uuid)

def _make_elementwise_binary_reference(prim: Callable, *, type_promotion_kind, aten_op=infer_aten_op, has_out=True, supports_lhs_python_scalar=True, supports_rhs_python_scalar=True) -> Callable:

    @elementwise_type_promotion_wrapper(type_promoting_args=('a', 'b'), type_promotion_kind=type_promotion_kind)
    def _ref(a: Union[Tensor, NumberType], b: Union[Tensor, NumberType]) -> Tensor:
        if not supports_lhs_python_scalar and isinstance(a, Number):
            raise ValueError('Received a lhs Python scalar to an elementwise binary operation that does not accept lhs scalars!')
        if not supports_rhs_python_scalar and isinstance(b, Number):
            raise ValueError('Received a rhs Python scalar to an elementwise binary operation that does not accept rhs scalars!')
        if isinstance(a, Number) and isinstance(b, Number) and (prim.__name__ != 'add'):
            raise ValueError(f'Receive two Number inputs to an elementwise binary operation {prim}!')
        (a, b) = _maybe_broadcast(a, b)
        return prim(a, b)
    if has_out:
        _ref = out_wrapper()(_ref)
    if aten_op is infer_aten_op:
        aten_op = getattr(torch.ops.aten, prim.__name__.split('.')[0])
    if aten_op is not None:
        register_decomposition(aten_op)(_ref)
    return _ref

