def update(self, req, node_id, body):
    node_data = body.get('node')
    if node_data is None:
        raise exc.HTTPBadRequest(_("Malformed request data, missing 'node' key in request body."))
    data = NodeData(node_data)
    updatable_fields = self.get_updatable_fields(data)
    if 'join' in updatable_fields or 'leave' in updatable_fields:
        self.handle_join_leave_updates(req.context, node_id, data)
    else:
        self.rpc_client.node_update(req.context, node_id, data.name(), data.profile_id(), data.role(), data.tags())
    raise exc.HTTPAccepted()

def get_updatable_fields(self, data):
    updatable_fields = []
    if data.name():
        updatable_fields.append('name')
    if data.profile_id():
        updatable_fields.append('profile_id')
    if data.role():
        updatable_fields.append('role')
    if data.tags():
        updatable_fields.append('tags')
    return updatable_fields

