def make_tuplet_from_proportions_and_pair(proportions, (n, d)):
    from abjad.tools import tuplettools
    proportions = mathtools.Ratio(proportions)
    assert proportions
    duration = durationtools.Duration(n, d)
    if len(proportions) == 1:
        if 0 < proportions[0]:
            try:
                return containertools.Container([notetools.Note(0, duration)])
            except AssignabilityError:
                return containertools.Container(notetools.make_notes(0, duration))
        elif proportions[0] < 0:
            try:
                return containertools.Container([resttools.Rest(duration)])
            except AssignabilityError:
                return containertools.Container(resttools.make_rests(duration))
        else:
            raise ValueError('no divide zero values.')
    if 1 < len(proportions):
        exponent = int(math.log(mathtools.weight(proportions), 2) - math.log(n, 2))
        denominator = int(d * 2 ** exponent)
        music = []
        for x in proportions:
            if not x:
                raise ValueError('no divide zero values.')
            if 0 < x:
                try:
                    music.append(notetools.Note(0, (x, denominator)))
                except AssignabilityError:
                    music.extend(notetools.make_notes(0, (x, denominator)))
            else:
                music.append(resttools.Rest((-x, denominator)))
        return tuplettools.FixedDurationTuplet(duration, music)

def Run(self, cmd_val):
    (attrs, offset) = arg_def.ParseCmdVal('unset', cmd_val)
    n = len(cmd_val.argv)
    arg = arg_types.unset(attrs.attrs)
    remaining_args = arg_r.Rest(cmd_val.argv, offset)
    for (name, spid) in remaining_args:
        if arg.f:
            if name in self.funcs:
                del self.funcs[name]
        elif arg.v:
            if not self._UnsetVar(name, spid, False):
                return 1
        elif not self._UnsetVar(name, spid, True):
            return 1
    return 0

def baseLevel(runthis, timeout, knownPath, logPrefix, valgrind=False):
    if valgrind:
        runthis = constructVgCmdList(errorCode=VALGRIND_ERROR_EXIT_CODE) + valgrindSuppressions(knownPath) + runthis
    wantStack = True
    runinfo = timedRun.timed_run(runthis, timeout, logPrefix, wantStack)
    sta = runinfo.sta
    lev = JS_FINE
    issues = []
    sawAssertion = False
    if detect_malloc_errors.amiss(logPrefix):
        issues.append('malloc error')
        lev = max(lev, JS_MALLOC_ERROR)
    if valgrind and runinfo.rc == VALGRIND_ERROR_EXIT_CODE:
        issues.append('valgrind reported an error')
        lev = max(lev, JS_VG_AMISS)
        valgrindErrorPrefix = '==' + str(runinfo.pid) + '=='
    else:
        valgrindErrorPrefix = None
    with open(logPrefix + '-err.txt', 'rb') as err:
        for line in err:
            assertion_info = detect_assertions.scanLine(knownPath, line)
            if assertion_info:
                (fatal, known) = assertion_info
                issues.append(line.rstrip())
                lev = max(lev, JS_NEW_ASSERT_OR_CRASH)
                if fatal:
                    sawAssertion = True
                    lev = max(lev, JS_KNOWN_CRASH)
            if valgrindErrorPrefix and line.startswith(valgrindErrorPrefix):
                issues.append(line.rstrip())
    if sawAssertion:
        pass
    elif sta == timedRun.CRASHED:
        if detect_interesting_crashes.amiss(knownPath, logPrefix + '-crash.txt', True):
            issues.append('unknown crash')
            lev = max(lev, JS_NEW_ASSERT_OR_CRASH)
        else:
            issues.append('known crash')
            lev = max(lev, JS_KNOWN_CRASH)
    elif sta == timedRun.TIMED_OUT:
        issues.append('timed out')
        lev = max(lev, JS_TIMED_OUT)
    elif sta == timedRun.ABNORMAL and (not (valgrind and runinfo.rc == VALGRIND_ERROR_EXIT_CODE)):
        issues.append('abnormal exit')
        lev = max(lev, JS_ABNORMAL_EXIT)
    return (lev, issues, runinfo)

def build_lp(model: calliope.Model, outfile: Union[str, Path], math: Optional[dict]=None, backend: Literal['pyomo']='pyomo') -> None:
    backend_instance = model._BACKENDS[backend]()
    backend_instance.add_all_parameters(model.inputs, model.run_config)
    for (name, dict_) in model.math['variables'].items():
        backend_instance.add_variable(model.inputs, name, dict_)
    if math is not None:
        for (component_group, component_math) in math.items():
            for (name, dict_) in component_math.items():
                getattr(backend_instance, f"add_{component_group.removesuffix('s')}")(model.inputs, name, dict_)
    if math is None or 'objectives' not in math.keys():
        backend_instance.add_objective(model.inputs, 'dummy_obj', {'equation': '1 + 1', 'sense': 'minimize'})
    backend_instance._instance.objectives[0].activate()
    backend_instance.verbose_strings()
    backend_instance.to_lp(str(outfile), symbolic_solver_labels=True)
    with Path(outfile).open('r') as f:
        stripped_lines = []
        while (line := f.readline()):
            stripped_lines.append(line.rstrip())
    Path(outfile).write_text('\n'.join(stripped_lines) + '\n')

