class Component:

    @classmethod
    def from_dict(cls, data):
        return cls(data)

class Button(Component):
    pass

class from_payload(cls, data, state):
    clicked_button_id = data['data']['custom_id']
    clicked_component_payload = None
    for action_row in data['message'].get('components', list()):
        for component in action_row.get('components', list()):
            if component.get('custom_id', None) == clicked_button_id:
                clicked_component_payload = component
                break
        if clicked_component_payload is not None:
            break
    if clicked_component_payload is None:
        clicked_component_payload = {'custom_id': clicked_button_id}
    clicked_component_object = Component.from_dict(clicked_component_payload)
    v = cls()
    v.data = data
    v._state = state
    v.component = clicked_component_object
    (channel, guild) = state._get_guild_channel(data)
    v.channel = channel
    v.guild = guild
    try:
        v.message = discord.Message(channel=channel, data=data['message'], state=state)
    except KeyError:
        v.message = discord.PartialMessage(channel=channel, id=int(data['message']['id']))
    if guild:
        v.user = discord.Member(data=data['member'], guild=guild, state=state)
    else:
        v.user = discord.User(data=data['user'], state=state)
    return v

import logging

def release_pgcon(self, dbname, conn, *, discard=False):
    if not conn.is_healthy_to_go_back_to_pool():
        logging.warning('Connection is not healthy to return to the pool for database: %s', dbname)
        discard = True
    self._pg_pool.release(dbname, conn, discard=discard)

def fromfile(cls, filename):
    fheader = path.splitext(filename)[0] + '.header'
    if path.isfile(fheader) and path.isfile(filename):
        with open(fheader, 'r', encoding='utf-8', errors='replace') as fd:
            for line in fd:
                if line.startswith('ArrayDesc('):
                    m = re.match(".*\\((\\d+),\\s*(\\d+).*dtype\\(\\'(.*)\\'\\).*", line)
                    if m:
                        shape = (int(m.group(2)), int(m.group(1)))
                        dtype = m.group(3)
                        return np.fromfile(filename, dtype).reshape(shape)
            raise NicosError('no ArrayDesc line found')
    else:
        raise NicosError('file and/or corresponding .header not found')

def translate_nd(self, source: mx.nd.NDArray, bucket_key: int) -> Tuple[np.ndarray, np.ndarray, float]:
    source_length = source.shape[1]
    max_output_length = min(source_length * C.TARGET_MAX_LENGTH_FACTOR, bucket_key * C.TARGET_MAX_LENGTH_FACTOR)
    return self._get_best_from_beam(*self._beam_search(source, bucket_key, max_output_length))

def S1s(self, sort_key='area', reverse=True, return_tpc=True, return_veto=False):
    peaks = self._get_peaks_by_type('s1', sort_key, reverse)
    if return_tpc and (not return_veto):
        return [peak for peak in peaks if peak.type.lower() == 'tpc']
    elif return_veto and (not return_tpc):
        return [peak for peak in peaks if peak.type.lower() == 'veto']
    return peaks

def _preprocess(self, dataset, fit=False):
    blocks_by_depth = self._dynamically_group_blocks_by_topology()
    input_node_ids = [self._node_to_id[input_node] for input_node in self.inputs]
    for blocks in blocks_by_depth:
        if fit:
            for (x, y) in dataset:
                x = nest.flatten(x)
                node_id_to_data = {node_id: temp_x for (temp_x, node_id) in zip(x, input_node_ids)}
                for block in blocks:
                    data = [node_id_to_data[self._node_to_id[input_node]] for input_node in block.inputs]
                    block.update(data, y=y)
            for block in blocks:
                block.finalize()
                nest.flatten(block.outputs)[0].shape = block.output_shape
        dataset = dataset.map(functools.partial(self._preprocess_transform, input_node_ids=input_node_ids, blocks=blocks, fit=fit))
        input_node_ids = list(sorted([self._node_to_id[block.outputs[0]] for block in blocks]))
    return dataset

def _dynamically_group_blocks_by_topology(self):
    blocks_by_depth = []
    return blocks_by_depth

