def show(request, uuid):
    try:
        connection = network.get_connection(uuid)
    except network.ConnectionNotFound:
        messages.error(request, _('Cannot show connection: Connection not found.'))
        return redirect(reverse_lazy('networks:index'))
    connection_status = network.get_status_from_connection(connection)
    try:
        active_connection = network.get_active_connection(uuid)
        active_connection_status = network.get_status_from_active_connection(active_connection)
    except network.ConnectionNotFound:
        active_connection_status = {}
        active_connection = None
    if active_connection and active_connection.get_devices():
        device = active_connection.get_devices()[0]
    else:
        interface_name = connection_status['interface_name']
        if interface_name:
            device = network.get_device_by_interface_name(interface_name)
        else:
            messages.error(request, _('Could not get device status: No interface name available.'))
            return redirect(reverse_lazy('networks:index'))
    device_status = network.get_status_from_device(device)
    access_point_status = None
    if connection_status['type'] == '802-11-wireless':
        access_point_status = network.get_status_from_wifi_access_point(device, connection_status['wireless']['ssid'])
    return TemplateResponse(request, 'connection_show.html', {'title': _('Show Connection information'), 'subsubmenu': subsubmenu, 'connection': connection_status, 'active_connection': active_connection_status, 'device': device_status, 'access_point': access_point_status})

def _analyze(self, oFile, oLine, iLineNumber):
    if oLine.__dict__[self.sTrigger]:
        words = self._extract(oLine)
        if self.case == 'lower':
            check_function = check.is_lowercase
            expected_case = str.lower
        else:
            check_function = check.is_uppercase
            expected_case = str.upper
        for word in words:
            if check_function(self, word, iLineNumber) == False:
                self.words_to_fix.add(word)
            if expected_case(word) != word:
                raise ValueError(f"Word '{word}' does not match expected case '{self.case}'.")

