def _stream_logs_to_output(self) -> None:
    if not self.cli:
        raise Exception("The 'cli' should be initialized before!")
    if not self.service:
        raise Exception("The 'service' should be initialized before!")
    logs = self.cli.service_logs(self.service['ID'], follow=True, stdout=True, stderr=True, is_tty=self.tty)
    line = ''
    while True:
        try:
            log = next(logs)
        except StopIteration:
            break
        else:
            try:
                log = log.decode()
            except UnicodeDecodeError:
                continue
            if log == '\n':
                self.log.info(line)
                line = ''
            else:
                line += log
    if line:
        self.log.info(line)

def _concatenate_components(reps_difs, names):
    values = []
    for name in names:
        data_vals = []
        for x in reps_difs:
            data_val = getattr(x, name)
            data_vals.append(data_val.reshape(1) if x.isscalar else data_val)
        concat_vals = np.concatenate(data_vals)
        values.append(concat_vals)
    return values

def get(method, hmc, uri, uri_parms, logon_required):
    cpc_oid = uri_parms[0]
    query_str = uri_parms[1]
    try:
        cpc = hmc.cpcs.lookup_by_oid(cpc_oid)
    except KeyError:
        new_exc = InvalidResourceError(method, uri)
        new_exc.__cause__ = None
        raise new_exc
    assert not cpc.dpm_enabled
    result_profiles = []
    filter_args = parse_query_parms(method, uri, query_str)
    for profile in cpc.image_activation_profiles.list(filter_args):
        result_profile = {}
        for prop in profile.properties:
            if prop in ('element-uri', 'name'):
                result_profile[prop] = profile.properties[prop]
        result_profiles.append(result_profile)
    if not result_profiles:
        raise ValueError('No image activation profiles found for the given parameters.')
    return {'image-activation-profiles': result_profiles}

def getMemberNames(self):
    assert self.isCollection
    childset = set()
    l = len(self.path)
    for f in self.provider.files:
        if f.startswith(self.path):
            p = f[l:]
            if '/' in p:
                p = p.split('/')[0]
            childset.add(p)
        elif childset:
            break
    return list(childset)

