def create_temp_user_avatar(self, user, filename, avatar_img, contentType=None, auto_confirm=False):
    avatar_img.seek(0, 2)
    size = avatar_img.tell()
    avatar_img.seek(0)
    params = {'username': user, 'filename': filename, 'size': size}
    headers = {'X-Atlassian-Token': 'no-check'}
    if contentType is not None:
        headers['content-type'] = contentType
    else:
        headers['content-type'] = self._get_mime_type(avatar_img)
    url = self._get_url('user/avatar/temporary')
    r = self._session.post(url, params=params, headers=headers, data=avatar_img)
    raise_on_error(r)
    cropping_properties = json.loads(r.text)
    if auto_confirm:
        return self.confirm_user_avatar(user, cropping_properties)
    else:
        return cropping_properties

def termdef(term):
    types = set((o.id for o in term.objects(RDF.type)))
    is_class = types & CLASS_TYPES
    is_prop = types & PROP_TYPES
    if not is_class and (not is_prop):
        return None
    if is_class:
        equiv = OWL.equivalentClass
        subof = RDFS.subClassOf
    else:
        equiv = OWL.equivalentProperty
        subof = RDFS.subPropertyOf
    target_candidates = [term.value(OWL.sameAs), term.value(equiv), term.value(subof)]
    target_term = next((candidate for candidate in target_candidates if candidate is not None), None)
    curie = unicode((target_term or term).qname())
    if is_class:
        return curie
    range_type = term.value(RDFS.range)
    range_iri = range_type and range_type.id
    if range_iri and range_iri.startswith(XSD) or range_iri == RDFS.Literal:
        datatype = range_type.qname()
    elif OWL.DatatypeProperty in types:
        datatype = False
    else:
        datatype = None
    if types & {RDF.Property, OWL.FunctionalProperty}:
        container = None
    elif range_iri == RDF.List:
        container = '@list'
    else:
        container = None
    reverse = None if target_term else term.value(OWL.inverseOf)
    if reverse or datatype or container:
        if reverse:
            dfn = {'@reverse': unicode(reverse.qname())}
        else:
            dfn = {'@id': curie}
        if datatype:
            dfn['@type'] = datatype
        elif datatype is False:
            dfn['@language'] = None
        if container:
            dfn['@container'] = container
        return dfn
    else:
        return curie

def _setup_jobs(self, job_names, skip_missing):
    jobs = []
    for job_name in job_names:
        if job_name == 'apt-get':
            job_name = 'apt'
        selection_name = self.solv.Selection.SELECTION_NAME
        selection_provides = self.solv.Selection.SELECTION_PROVIDES
        selection = self.pool.select(job_name, selection_name | selection_provides)
        if selection.flags & self.solv.Selection.SELECTION_PROVIDES:
            log.info('--> Using capability match for {0}'.format(job_name))
        if selection.isempty():
            if skip_missing:
                log.info('--> Package {0} not found: skipped'.format(job_name))
            else:
                raise KiwiSatSolverJobError('Package {0} not found'.format(job_name))
        else:
            jobs += selection.jobs(self.solv.Job.SOLVER_INSTALL)
    return jobs

def get_widget_instance_dict(self, customization_args, context_params, kvps_only=False):
    param_dict = {}
    for param in self.params:
        param_dict[param.name] = {'value': params.get(param.name, param.value), 'obj_type': param.obj_type, 'choices': param.choices}
    if kvps_only:
        for param in param_dict:
            param_dict[param] = param_dict[param]['value']
    result = {'name': self.name, 'category': self.category, 'description': self.description, 'id': self.id, 'raw': self.get_raw_code(customization_args, context_params), 'params': param_dict}
    if self.type == feconf.INTERACTIVE_PREFIX:
        result['handlers'] = [h.to_dict() for h in self.handlers]
        for (idx, handler) in enumerate(self.handlers):
            result['handlers'][idx]['rules'] = dict(((rule_cls.description, {'classifier': rule_cls.__name__}) for rule_cls in handler.rules))
    return result

def __get_cwd(self, cwd) -> str:
    config = self.config
    if config.get('IsLayer'):
        bottle = f"{Paths.layers}/{config['Path']}"
    elif config.get('Environment', 'Custom') == 'Steam':
        bottle = config.get('Path')
    else:
        bottle = ManagerUtils.get_bottle_path(config)
    if not cwd:
        cwd = config.get('WorkingDir')
    if cwd == '' or not os.path.exists(cwd):
        cwd = bottle
    return cwd

def ProcessDirectory(self, responses):
    if responses.success:
        response = responses.First()
        if response is None:
            return
        directory_pathspec = response.pathspec.Dirname()
        urn = directory_pathspec.AFF4Path(self.client_urn)
        self.StoreDirectory(responses)
        if self.state.first_directory is None:
            self.state.first_directory = urn
        else:
            relative_name = urn.RelativeName(self.state.first_directory) or ''
            if len(relative_name) >= self.args.max_depth:
                self.Log('Exceeded maximum path depth at %s.', urn.RelativeName(self.state.first_directory))
                return
        for stat_response in responses:
            is_dir = stat.S_ISDIR(int(stat_response.st_mode))
            if not stat_response.symlink and is_dir:
                self.CallClient(server_stubs.ListDirectory, pathspec=stat_response.pathspec, next_state='ProcessDirectory')
                self.state.dir_count += 1
                if self.state.dir_count % 100 == 0:
                    self.Log('Reading %s. (%d nodes, %d directories done)', urn.RelativeName(self.state.first_directory), self.state.file_count, self.state.dir_count)
        self.state.file_count += len(responses)

def powerup_application(args):
    alliance = args['alliance']
