def hook(self, repo_id=None, **post):
    if repo_id is None:
        repository = post.get('repository')
        if repository and 'ssh_url' in repository:
            ssh_url = repository['ssh_url']
            repo = request.env['runbot.repo'].sudo().search([('ssh_url', '=', ssh_url)], limit=1)
        else:
            return 'Repository information is missing.'
    else:
