def __storebytype(self):
    assert self.loaded
    for n in self.actions_bytype.keys():
        with tempfile.NamedTemporaryFile(delete=False, dir=self.__file_path('')) as f:
            for a in self.actions_bytype[n]:
                f.write(f'{a}\n'.encode())
        portable.rename(f.name, self.__file_path(f'manifest.{n}'))
    with tempfile.NamedTemporaryFile(delete=False, dir=self.__file_path('')) as f:
        dirs = self.__actions_to_dirs()
