def process_sig_rx(self, dict_sig=None):
    logger.debug('Processing {0} | needs_draw = {1}, visible = {2}'.format(dict_sig, self.needs_draw, self.isVisible()))
    if self.isVisible():
        if 'data_changed' in dict_sig or 'specs_changed' in dict_sig or 'home' in dict_sig or self.needs_draw:
            self.draw()
            self.needs_draw = False
            self.needs_redraw = False
        elif 'ui_changed' in dict_sig and dict_sig['ui_changed'] == 'resized' or self.needs_redraw:
            self.redraw()
            self.needs_redraw = False
        elif 'view_changed' in dict_sig:
            self.update_view()
    elif 'data_changed' in dict_sig or 'specs_changed' in dict_sig:
        self.needs_draw = True
    elif 'ui_changed' in dict_sig and dict_sig['ui_changed'] == 'resized':
        self.needs_redraw = True

def _update(self, do_immediate):
    toplevel = self.get_toplevel()
    if not toplevel or not toplevel.is_toplevel():
        return
    self.opened = False
    if self.pinned:
        do_immediate = True
        self.opened = True
    (x, y) = self.eventBox.get_pointer()
    alloc = self.eventBox.get_allocation()
    if x > -1 and y > -1 and (x < alloc.width) and (y < alloc.height):
        self.opened = True
    focus = toplevel.get_focus()
    if focus and focus.is_ancestor(self.eventBox):
        do_immediate = True
        self.opened = True
    if not self.inputUngrabbed:
        grabbed = Gtk.grab_get_current()
        if grabbed and isinstance(grabbed, Gtk.Menu):
            while True:
                menuAttach = grabbed.get_attach_widget()
                if not menuAttach:
                    break
                grabbed = menuAttach
                if not isinstance(grabbed, Gtk.MenuItem):
                    break
                menuItemParent = grabbed.get_parent()
                if not isinstance(menuItemParent, Gtk.Menu):
                    break
                grabbed = menuItemParent
        if grabbed and grabbed.is_ancestor(self.eventBox):
            do_immediate = True
            self.opened = True
    if self.delayConnection:
        GLib.source_remove(self.delayConnection)
    if self.forceClosing:
        self._enforce(True)
    elif do_immediate:
        self._enforce(False)
    else:
        self.delayConnection = GLib.timeout_add(self.delayValue, self._on_enforce_delay)

def get_units(self, unit_type_id=None, filters=None, fields=None):
    try:
        content_units = []
        associated = self.__association_manager.get_unit_ids(self.repo_id, unit_type_id)
        for (unit_type, unit_ids) in associated.items():
            if filters:
                filtered_ids = self.apply_filters(unit_ids, filters)
            else:
                filtered_ids = unit_ids
            units = self.__content_query_manager.list_content_units(unit_type, {'_id': {'$in': filtered_ids}}, fields)
            type_def = types_db.type_definition(unit_type)
            if type_def is None:
                continue
            for unit in units:
                u = common_utils.to_plugin_unit(unit, type_def)
                content_units.append(u)
        return content_units
    except Exception as e:
        _LOG.exception('Error getting units for repository [%s]' % self.repo_id)
        raise RepoPublishConduitException(e) from None

def getBuiltinIter2Code(callable_identifier, sentinel_identifier, export=False):
    code = 'BUILTIN_ITER2( %s, %s )' % (callable_identifier.getCodeTemporaryRef(), sentinel_identifier.getCodeTemporaryRef())
    if export:
        return (Identifier(code, 1), callable_identifier, sentinel_identifier)
    return Identifier(code, 1)

def combined_nav_link(text, routename, **kwargs):
    class_ = _link_class(kwargs)
    return link_to(text, url_for(str(routename), **kwargs), class_=class_)
subnav_named_route = combined_nav_link

def isSpecificCaseOf(self, other):
    if isinstance(other, Atom):
        return self.equivalent(other)
    elif isinstance(other, GroupAtom):
        cython.declare(atom=GroupAtom, a=AtomType, radical=cython.short, charge=cython.short)
        atom = other
        if self.atomType is None:
            return False
        for a in atom.atomType:
            if self.atomType.isSpecificCaseOf(a):
                break
        else:
            return False
        for radical in atom.radicalElectrons:
            if self.radicalElectrons == radical:
                break
        else:
            return False
        for charge in atom.charge:
            if self.charge == charge:
                break
        else:
            return False
        return True

def build_requirements(self):
    if cross_building(self, skip_x64_x86=True) and hasattr(self, 'settings_build'):
        self.tool_requires('gsoap/{}'.format(self.version))
    if self.is_msvc():
        self.tool_requires('winflexbison/2.5.24')
    else:
        self.tool_requires('bison/3.7.6')
        self.tool_requires('flex/2.6.4')

def object_by_uid(self, uid, comp_filter=None):
    data = cdav.CalendarData()
    prop = dav.Prop() + data
    query = cdav.TextMatch(uid)
    query = cdav.PropFilter('UID') + query
    if comp_filter:
        query = comp_filter + query
    vcalendar = cdav.CompFilter('VCALENDAR') + query
    filter = cdav.Filter() + vcalendar
    root = cdav.CalendarQuery() + [prop, filter]
    response = self._query(root, 1, 'report')
    if response.status == 404:
        raise error.NotFoundError(errmsg(response))
    elif response.status == 400:
        raise error.ReportError(errmsg(response))
    items_found = response.tree.findall('.//' + dav.Response.tag)
    for r in items_found:
        href = unquote(r.find('.//' + dav.Href.tag).text)
        data = unquote(r.find('.//' + cdav.CalendarData.tag).text)
        data = self._unfold_content(data)
        if not f'\nUID:{uid}\n' in data:
            continue
        return self._calendar_comp_class_by_data(data)(self.client, url=URL.objectify(href), data=data, parent=self)
    raise error.NotFoundError(errmsg(response))

def _unfold_content(self, data):
    return ' '.join(data.splitlines())

def has_perms(self):
    group_perms = get_groups_with_perms(self, attach_perms=True)
    for perms in group_perms.values():
        for perm in perms:
            if perm != self.add_permission_name:
                return True
    return False

def _update_mirror_status(self):
    mstate = self._get_mirror_state()
    if mstate == MIRROR_NOT_REFD:
        txt_warning = 'Parking the mirror at least once is required in order to reference the actuators.'
    elif mstate == MIRROR_BAD:
        txt_warning = 'The mirror is neither fully parked nor entirely engaged.'
    else:
        txt_warning = None
    self.panel.pnl_ref_msg.Show(txt_warning is not None)
    if txt_warning:
        self.panel.txt_warning.SetLabel(txt_warning)
        self.panel.txt_warning.Wrap(self.panel.pnl_ref_msg.Size[0] - 16)
    if mstate == MIRROR_PARKED:
        btn_text = 'ENGAGE MIRROR'
    else:
        btn_text = 'PARK MIRROR'
    self.panel.btn_switch_mirror.SetLabel(btn_text)
    self.update_tab_states(mstate)
    self.highlight(mstate != MIRROR_ENGAGED)

def update_tab_states(self, mstate):
    if mstate == MIRROR_ENGAGED:
        self.panel.alignment_tab.Enable()
    else:
        self.panel.alignment_tab.Disable()

def dispatch_commands(protocol_data, loaded_pipettes, loaded_labware):
    subprocedures = [p.get('subprocedure', []) for p in protocol_data.get('procedure', [])]
    default_values = protocol_data.get('default-values', {})
    flat_subs = chain.from_iterable(subprocedures)
    for command_item in flat_subs:
        command_type = command_item.get('command')
        params = command_item.get('params', {})
        pipette = _get_pipette(params, loaded_pipettes)
        pipette_model = protocol_data.get('pipettes', {}).get(params.get('pipette'), {}).get('model')
        location = _get_location(loaded_labware, command_type, params, default_values)
        volume = params.get('volume')
        if pipette:
            _set_flow_rate(pipette_model, pipette, command_type, params, default_values)
        if command_type == 'delay':
            wait = params.get('wait')
            if wait is None:
                raise ValueError('Delay cannot be null')
            elif wait is True:
                message = params.get('message', 'Pausing until user resumes')
                robot.comment(message)
                robot.pause()
            else:
                _sleep(wait)
        elif command_type == 'blowout':
            pipette.blow_out(location)
        elif command_type == 'pick-up-tip':
            pipette.pick_up_tip(location)
        elif command_type == 'drop-tip':
            pipette.drop_tip(location)
        elif command_type == 'aspirate':
            pipette.aspirate(volume, location)
        elif command_type == 'dispense':
            pipette.dispense(volume, location)
        elif command_type == 'touch-tip':
            pipette.touch_tip(location)

def _log_args(self, variables):
    args = ['${%s}' % arg for arg in self.arguments.positional]
    if self.arguments.varargs:
        args.append('@{%s}' % self.arguments.varargs)
    args = ['%s=%s' % (name, utils.safe_repr(variables[name])) for name in args]
    kwargs = ['&{%s}' % key for key in variables if key not in self.arguments.positional]
    args.extend(kwargs)
    return 'Arguments: [ %s ]' % ' | '.join(args)

def execute(self, args):
    manuals = man_pages.all_man_pages()
    check_infos = {}
    for (check_plugin_name, check) in config.check_info.items():
        try:
            manfile = manuals.get(check_plugin_name)
            if manfile:
                title = man_pages.get_title(manfile)
            else:
                title = check_plugin_name
            check_infos[check_plugin_name] = {'title': six.ensure_text(title)}
            if check['group']:
                check_infos[check_plugin_name]['group'] = check['group']
            check_infos[check_plugin_name]['service_description'] = check.get('service_description', '%s')
            check_infos[check_plugin_name]['snmp'] = cmk.base.check_utils.is_snmp_check(check_plugin_name)
        except Exception as e:
            if cmk.utils.debug.enabled():
                raise
            raise MKAutomationError("Failed to parse man page '%s': %s" % (check_plugin_name, e))
    return check_infos

def __repr__(self):
    try:
        query_result = self._build_query()
        result_count = len(query_result)
        execution_time = '1ms'
        first_row = query_result[0] if result_count > 0 else 'No results'
        return '<Select {0}, {1} results, {2}, First row: {3}>'.format(repr(query_result), result_count, execution_time, first_row)
    except RuntimeError:
        return repr(self._filters)

def compile(self):
    self.router.reset()
    for (_, method_tuple) in self.methods.items():
        (method, method_config) = method_tuple
        self.router.add_method_handler(method_call=method, method_config=method_config)
    (self.approval_program, self.clear_program, self.contract) = self.router.compile_program(version=self.teal_version, assemble_constants=True, optimize=OptimizeOptions(scratch_slots=True))

def __call__(self, *args, **kwargs):
    default_height = 512
    default_width = 512
    if hasattr(self, 'is_statically_reshaped') and self.is_statically_reshaped:
        height = kwargs.get('height', default_height)
        width = kwargs.get('width', default_width)
    else:
        height = kwargs.get('height')
        width = kwargs.get('width')
    if args and isinstance(args[0], Image.Image):
        image = args[0]
        if image.height != height or image.width != width:
            image = image.resize((width, height))
            args = (image,) + args[1:]
    return StableDiffusionImg2ImgPipelineMixin.__call__(self, *args, **kwargs)

def select(cls, clause=None, having=None, connection=None, order_by=None, distinct=None):
    (attributes, columns) = zip(*cls.columns.items())
    if connection is None:
        from stoqlib.database.runtime import get_connection
        connection = get_connection()
    store = connection.store
    clauses = []
    if clause:
        clauses.append(clause)
    if cls.clause:
        clauses.append(cls.clause)
    if clauses:
        clauses = [AND(*clauses)]
    tables = cls._get_tables_for_query(cls.tables[:], clause)

    def _load_view_objects(result, values):
        instance = cls()
        instance._connection = connection
        for (attribute, value) in zip(attributes, values):
            if hasattr(cls.columns[attribute], 'variable_factory'):
                var = cls.columns[attribute].variable_factory.func()
                if value is not None:
                    value = var.parse_set(value, False)
            setattr(instance, attribute, value)
        return instance
    results = store.using(*tables).find(columns, *clauses)
    if cls.group_by:
        results = results.group_by(*cls.group_by)
    if order_by:
        results = results.order_by(order_by)
    if distinct:
        results.config(distinct=True)
    results._load_objects = _load_view_objects
    results.orderBy = results.order_by
    return results

def upload_object_via_stream(self, iterator, container, object_name, extra=None, ex_storage_class=None):
    method = 'PUT'
    params = None
    if self.supports_s3_multipart_upload:
        multipart_upload = self._initialize_multipart_upload(container, object_name, ex_storage_class)
        part_number = 1
        for chunk in iterator:
            self._upload_part(multipart_upload['upload_id'], part_number, chunk)
            part_number += 1
        self._complete_multipart_upload(multipart_upload['upload_id'], container, object_name)
        return
    return self._put_object(container=container, object_name=object_name, extra=extra, method=method, query_args=params, stream=iterator, verify_hash=False, storage_class=ex_storage_class)
